-- Generated by QuestData/Tools/import_multilanguage_quests.py.
-- Known IDs only; Classic-source passages are compatibility fallbacks on Forever.
local source = "MultiLanguage Classic c51dc2e5141f070f5b92de190521d79e8dccaeab"
local data = WordHunterWoW_QuestDataByFlavor
local function apply(id, targets, passages)
    for _, flavor in ipairs(targets) do
        local languages = data and data[flavor]
        for locale, fields in pairs(passages) do
            local record = languages and languages[locale] and languages[locale][id]
            if record then
                for field, text in pairs(fields) do
                    if not record[field] or record[field] == "" then
                        record[field] = text
                        record[field .. "Source"] = source
                        record[field .. "SourceFlavor"] = "classic"
                    end
                end
            end
        end
    end
end

apply(6029, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {class}. Im Namen der Argentumdämmerung biete ich Euch Sicherheit und Unterkunft, solange Ihr hier im Bollwerk seid. Ich könnte Euch auch die Möglichkeit bieten, für eine Sache zu kämpfen, für die es sich zu kämpfen lohnt!", completion = "Gregor ist außerordentlich findig für einen Menschen. Er hat schon seit geraumer Zeit mit dem Steamwheedle-Kartell zu tun und ist ein Experte in der 'Kunst' von Goblin-Verhandlungen geworden. Es stimmt zwar, dass die Goblins weitgehend denen mit den größten Geldbörsen gegenüber loyal sind, aber sie kennen und achten auch den Wert der Diplomatie. Sie bringt ihnen immerhin Kunden ein, die wiederkommen ...\n\nWie auch immer, die Argentumdämmerung dankt Euch für Eure Bemühungen. Bitte nehmt dies mit unserem Dank." }, enUS = { progress = "Greetings, {class}.  On behalf of the Argent Dawn, I offer you safety and shelter while you are here at Bulwark.  I might also offer you the chance to fight for a cause that's worth fighting for!", completion = "Resourceful for a human, Gregor is.  He's been dealing with the Steamwheedle Cartel for some time now, and has become an expert on the \"art\" of goblin negotiations.  Though it's true that the goblins' primary loyalties lie with those who have the largest coin purses, they also know and respect the value of diplomacy.  If anything, it provides them with repeat customers...\n\nAt any rate, the Argent Dawn acknowledges you for your effort.  Please have this, with our thanks." } })
apply(6030, { "classic", "forever" }, { deDE = { progress = "Möge das Licht Euch in diesen gefährlichen Zeiten leiten, {class}. Was führt Euch zu diesem Fanal der Hoffnung inmitten von Dunkelheit und Verzweiflung?", completion = "Das... ist ein ganz besonderes Buch, das Ihr mir da gebracht habt. Ich würde Euch gern sagen, dass 'besonders' in diesem Fall 'einzigartig und höchstwahrscheinlich lehrreich' bedeutet, doch das wird man sehen.\n\n\"Ooooooh?\" Wer sich so etwas ausdenkt, kann doch nicht bei klarem Verstand sein?\n\nAber ich habe von diesem Umbranse gehört, von dem Gregor sprach, daher ist das hier nicht ganz wertlos. Ich tue mein Bestes, es zu entziffern. Und was Euch angeht... bitte nehmt dies... mit freundlichen Grüßen der Argentumdämmerung. Da Ihr schon mal hier seid, vielleicht könnt Ihr uns noch bei anderen Dingen unterstützen." }, enUS = { progress = "May the Light guide you in these troubling times, {class}.  What brings you here to this beacon of hope in the middle of darkness and despair?", completion = "This... this is a very special book you have brought me.  I'd like to tell you that \"special\" in this case means \"unique and quite possibly illuminating\", but that remains to be seen.\n\n\"Ooooooo?\"  Who in their right mind thinks this up?\n\nWell now, I've heard of this Umbranse that Gregor spoke of, so this isn't without merit.  I'll do my best to decipher it.  As for you... please, have this - courtesy of the Argent Dawn.  While you are here, perhaps there are some other things you can aid us with." } })
apply(6031, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Runenstoff? Mein Volk ist ganz gierig nach weiteren Kleidungsstücken aus Runenstoff!", completion = "Ah, Ihr habt den Stoff. Was für ein herrliches Material!\n\nDanke, {name}. Ihr seid ein wahrer Freund. Bitte nehmt dies als Gegenleistung." }, enUS = { progress = "Do you have the runecloth?  My people are eager for more items of runecloth!", completion = "Ah, you brought the cloth.  Such fine material it is!\n\nThank you, {name}.  You are a true friend.  Please accept this in exchange." } })
apply(6032, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Mondstoff dabei, {name}?", completion = "Ah, sehr gut. Dieser Mondstoff wird für Gewänder benutzt, die für unser Volk hochheilig sind. Danke, {name}. Jetzt werde ich Euch ausbilden." }, enUS = { progress = "Have you brought the mooncloth, {name}?", completion = "Ah, very good.  This mooncloth will be used for garments sacred to our people.  Thank you, {name}.  Now I will train you." } })
apply(6042, { "classic", "forever" }, { deDE = { completion = "Unglaublich, was ein wenig Zorn und Wut doch bewirken können." }, enUS = { completion = "It's incredible what a little anger and rage can get accomplished." } })
apply(6061, { "classic", "forever" }, { deDE = { progress = "Übt Eure Fertigkeiten, {name}. Zähmt den ausgewachsenen Ebenenschreiter.", completion = "Die Erdenmutter hat mir Zeichen geschickt. Ihr habt Eure Sache gut gemacht." }, enUS = { progress = "Practice your skills, {name}. Tame the adult plainstrider.", completion = "Signs have appeared to me from the Earthmother; you have done well." } })
apply(6062, { "classic", "forever" }, { deDE = { progress = "Viel Glück, junger {class}.", completion = "Ihr habt Eure Sache gut gemacht, {name}. Ich glaube, Ihr seid bereit für die nächste Aufgabe." }, enUS = { progress = "Good luck, young {class}.", completion = "You have done well, {name}. I believe you are ready for your next task." } })
apply(6063, { "classic", "forever" }, { deDE = { progress = "Ihr werdet lernen, {name}, und eines Tages ein großer {class} sein.", completion = "Exzellent, {name}! Ihr lernt wirklich sehr schnell." }, enUS = { progress = "You will learn, {name}, and one day you will be a great {class}.", completion = "Excellent, {name}! You are quite a fast learner." } })
apply(6068, { "classic", "forever" }, { deDE = { completion = "Ja, ich glaube auch, Ihr seid bereit..." }, enUS = { completion = "Yes, I do believe you are ready, as well...." } })
apply(6069, { "classic", "forever" }, { deDE = { completion = "Ja, ich glaube, Ihr seid bereit für die Ausbildung..." }, enUS = { completion = "Yes, I believe you are ready to be trained..." } })
apply(6070, { "classic", "forever" }, { deDE = { completion = "Ja, ich glaube, es ist an der Zeit, dass ich Euch ausbilde..." }, enUS = { completion = "Yes, I believe that it is time for me to train you..." } })
apply(6071, { "classic", "forever" }, { deDE = { completion = "Ja, es ist an der Zeit, {class}." }, enUS = { completion = "Yes, it is time, {class}." } })
apply(6073, { "classic", "forever" }, { deDE = { completion = "Ja, es ist an der Zeit, Euch auszubilden..." }, enUS = { completion = "Yes, it is time to train you..." } })
apply(6075, { "classic", "forever" }, { deDE = { completion = "Ja, ich glaube, es ist an der Zeit, dass Ihr ausgebildet werdet..." }, enUS = { completion = "Yes, I believe that it is time for you to be trained..." } })
apply(6076, { "classic", "forever" }, { deDE = { completion = "Ja, {class}, es ist Zeit..." }, enUS = { completion = "Yes, {class}, it is time..." } })
apply(6081, { "classic", "forever" }, { deDE = { completion = "Ein junger {class} seid Ihr, ich verstehe. Ja, ich gewähre Euch die Fertigkeiten, die Ihr braucht, um Euer neues Tier auszubilden und zu führen. Ihr werdet Eurem Tier nicht nur neue Fähigkeiten beibringen können, sondern Ihr könnt es auch füttern und wiederbeleben, sollte es im Kampf fallen.\n\nGeht jetzt, {class}. Wir sprechen uns zu einem späteren Zeitpunkt wieder." }, enUS = { completion = "A young {class}, I see. Yes, I will grant you the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.\n\nNow, go, {class}. We will speak again, at a later date." } })
apply(6082, { "classic", "forever" }, { deDE = { progress = "Konntet Ihr den Skorpid zähmen?", completion = "Ihr habt gelernt, was ich Euch beibringen konnte, {name}. Es ist Zeit, dass Ihr das Gelernte anwendet und Euch ein eigenes Tier wählt.\n\nHier, bitte schön, {name}. Ich gebe Euch jetzt die Macht, ein Tier zu zähmen und es nach Belieben zu rufen und wegzuschicken. Benutzt Eure neuen Fertigkeiten voller Stolz; Ihr habt sie Euch verdient." }, enUS = { progress = "Were you able to tame the scorpid?", completion = "You have learned all I can teach you, {name}. It is time for you to take what you have learned here and choose a pet of your own.\n\nHere you are, {name}. I will now give you the power to tame a beast, as well as call it and dismiss it as you see fit. Use your new skills with pride; you have earned them." } })
apply(6083, { "classic", "forever" }, { deDE = { progress = "Ihr müsst üben, damit Ihr die Fertigkeiten erlangt, die Ihr braucht, um Euer Tier wirksam zu kontrollieren. Habt Ihr schon einen Brandungskriecher gezähmt?", completion = "Ihr lernt schnell, {name}. Das habt Ihr gut gemacht." }, enUS = { progress = "You need to practice in order to gain the skills you need to effectively control your pet. Have you tamed a surf crawler?", completion = "You are a swift learner, {name}. You have done well." } })
apply(6084, { "classic", "forever" }, { deDE = { progress = "Was haltet Ihr von dem Schneeleoparden, {name}?", completion = "Wenn ich glaube, dass Ihr genug gelernt habt, gewähre ich Euch die Fähigkeit, jedes Tier zu wählen, das Euch gefällt." }, enUS = { progress = "What do you think of the snow leopard, {name}?", completion = "When I feel you've learned enough, I will grant you the ability to choose any pet of your liking." } })
apply(6085, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Eisklauenbären schon gezähmt?", completion = "Hier, bitte schön, {name}. Ich geb Euch jetzt die Macht, ein Tier zu zähmen und es nach Belieben zu rufen und wegzuschicken.\n\nSucht Euch ein gutes, treues Tier und genießt die Jagd!" }, enUS = { progress = "Have you tamed the ice claw bear yet?", completion = "Here you are, {name}. I will now give ya the power to tame a beast, as well as call it and dismiss it as you please.\n\nFind yerself a good, loyal pet, and enjoy the hunt!" } })
apply(6087, { "classic", "forever" }, { deDE = { progress = "Habt Ihr schon einen Präriepirscher gefunden?", completion = "Ja... Die Erdenmutter glaubt, Ihr seid bereit für die nächste Lektion." }, enUS = { progress = "Have you found a prairie stalker?", completion = "Yes... The Earthmother believes that you are ready for the next lesson." } })
apply(6088, { "classic", "forever" }, { deDE = { progress = "Ihr werdet bald bereit sein, {name}.", completion = "Ihr habt gelernt, was ich Euch beibringen konnte, {name}. Möge der Segen der Erdenmutter Euch bei der Wahl Eures Tiers leiten.\n\nHier, bitte schön, {name}. Ich gebe Euch jetzt die Macht, ein Tier zu zähmen und es nach Belieben zu rufen und wegzuschicken. Benutzt Eure neuen Fertigkeiten voller Stolz und ehrt die Erdenmutter." }, enUS = { progress = "You will soon be ready, {name}.", completion = "You have learned all I can teach you, {name}. May the blessings of the Earthmother guide you in choosing a pet.\n\nHere you are, {name}. I will now give you the power to tame a beast, as well as call it and dismiss it as you see fit. Use your new skills with pride and honor the Earthmother." } })
apply(6089, { "classic", "forever" }, { deDE = { completion = "Ein junger {class} seid Ihr, ich verstehe. Ja, ich kann Euch die Fertigkeiten verleihen, die Ihr braucht, um Euer Tier auszubilden und zu führen. Ihr werdet Eurem Tier nicht nur neue Fähigkeiten beibringen können, sondern Ihr könnt es auch füttern und wiederbeleben, sollte es im Kampf fallen.\n\nGeht jetzt. Möge die Erdenmutter Euch auf Eurem Weg geleiten. Wir sprechen uns zu einem späteren Zeitpunkt wieder." }, enUS = { completion = "A young {class}, I see. Yes, I can bestow you with the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.\n\nNow, go forth. May the Earthmother guide you on your path. We shall speak again, at a later date." } })
apply(6101, { "classic", "forever" }, { deDE = { progress = "Es liegt in der Natur jedes Nachtelfen, dass er das Gleichgewicht zwischen der Natur und sich selbst begreift.", completion = "Ich sehe, dass Ihr entschlossen seid und verstanden habt, was ich Euch gelehrt habe, {name}." }, enUS = { progress = "Understanding the balance between nature and oneself is a way of life for every {race}.", completion = "I see your commitment and that you have understood what I have taught you, {name}." } })
apply(6102, { "classic", "forever" }, { deDE = { progress = "Ich bin stolz auf Eure Leistungen, {name}. Habt Ihr die letzte Aufgabe vollendet, die ich Euch gab?", completion = "Ihr habt gelernt, was ich Euch beibringen konnte, {name}. Lasst mich Euch noch einen Rat geben: Seid umsichtig, wenn Ihr Euer erstes Tier wählt. Soll es eine Kreatur des Landes, des Wassers oder des Himmels sein? Was auch immer, Euer Tier wird zweifellos eine ganze Weile bei Euch sein.\n\nHier, bitte schön, {name}. Ich gebe Euch jetzt die Macht, ein Tier zu zähmen und es nach Belieben zu rufen und wegzuschicken. Benutzt Eure neuen Fertigkeiten voller Stolz; Ihr habt sie Euch verdient." }, enUS = { progress = "I am proud of your accomplishments, {name}. Have you finished the last task I gave you?", completion = "You have learned all I can teach you, {name}. May I offer you one more piece of advice: use discretion when choosing your first pet. Will you choose a creature of the land, of the water, or of the sky? Whatever it may be, without doubt, your pet will be with you for quite some time.\n\nHere you are, {name}. I will now give you the power to tame a beast, as well as call it and dismiss it as you see fit. Use your new skills with pride; you have earned them." } })
apply(6103, { "classic", "forever" }, { deDE = { completion = "Ein angehender {class} seid Ihr, ich verstehe. Ja, ich kann Euch die Fertigkeiten verleihen, die Ihr braucht, um Euer Tier auszubilden und zu führen. Ihr werdet Eurem Tier nicht nur neue Fähigkeiten beibringen können, sondern Ihr könnt es auch füttern und wiederbeleben, sollte es im Kampf fallen.\n\nDenkt daran, {name}, respektiert stets das Gleichgewicht und lebt in Ehrfurcht vor der Natur ringsum. Geht jetzt. Wir sprechen uns zu einem späteren Zeitpunkt wieder." }, enUS = { completion = "A fledgling {class}, I see. Yes, I can bestow you with the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.\n\nRemember, {name}, always respect the balance and live in awe of nature around you. Now, go forth. We shall speak again, at a later date." } })
apply(6121, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, junger {class}, ich sehe mit Freuden, dass Ihr begierig seid, etwas über die Heilung von Vergiftungen zu lernen.\n\nFrüher wurden die meisten Druiden vorab geplanten Prüfungen unterzogen, doch das trifft auf Euch nicht zu. In Auberdine traten vermehrt Fälle von Tiervergiftungen auf und die Dorfbewohner konnten sie nicht heilen. Aus diesem Grund bat ein Repräsentant Moonglade um Hilfe. Wir schicken Euch zu ihrer Unterstützung dorthin. Dies ist keine Übung - es handelt sich um eine echte Aufgabe. Vergesst das nicht." }, enUS = { completion = "Greetings young {class}, I'm glad to see you ready and eager to learn about the curing of poisons.\n\nWhile most druids in the past were put through pre-planned trials, your work will involve no such thing.  There has been a rash of animal poisonings in Auberdine, and the village there has been unable to cure it.  To that end, a representative there has asked Moonglade for aid and we are sending you there to aid them.  This is no exercise - the work you'll do is quite real.  Bear this in mind." } })
apply(6122, { "classic", "forever" }, { deDE = { progress = "Seid Ihr vom Zirkel des Cenarius in Moonglade geschickt worden? Das ist wunderbar! Wir haben hier eine echte Krisensituation, was das Wild angeht, und sind dankbar für jedwede Hilfe.\n\nHabt Ihr die Probe des Wassers, wie Dendrite Starblaze sagte? Er informierte mich, dass Ihr eine besorgen würdet, damit wir gemeinsam ein Heilmittel finden ...", completion = "Bei Elune, dieses Wasser ist widerwärtig! Kein Wunder, dass das Wild krank ist.\n\nEtwas verunreinigt das Wasser und damit Dunkelküstes gesamten Wasservorrat. Man hat überall in der Gegend krankes Wild gesehen, nicht nur am Fluss. Das Wasser ist wahrscheinlich der Hauptgrund für die Ausbreitung der Krankheit, aber hier wirkt noch etwas anderes.\n\nDieses Wasser wird uns, ob Ihr es glaubt oder nicht, ein Heilmittel finden helfen. Während ich dieses Wasser untersuche benötige ich einige Zutaten für ein Heilmittel..." }, enUS = { progress = "You're the one that the Cenarion Circle in Moonglade sent?  That's wonderful!  We've quite the crisis our hands here regarding the poor deer, and we're happy for all the help we can get.\n\nDo you have the sample of water that Dendrite Starblaze said you'd have?  He notified me that you'd draw one so we could work on a cure together...", completion = "By Elune, this water is disgusting!  No wonder the deer are sick.\n\nSomething is polluting the water, and in turn corrupting Darkshore's entire water table.  Sick deer have been seen all over area, and not just by the river.  While this water is most likely a primary source of the sickness spreading, there's something else at work here.\n\nThis water, believe it or not, will help us formulate a cure.  While I research this water, I have need of some items to formulate a cure..." } })
apply(6123, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Reagenzien bekommen, die ich für meine Salbe brauche? Das Wild wird von allein ganz bestimmt nicht wieder gesund, daher sollten wir uns besser beeilen!", completion = "Das ist gut, {name}, so sehr, dass es für eine gehörige Portion Salbe reichen müsste - wenigstens so viel, dass eine Wirkung zu spüren ist.\n\nManchmal kann es recht schwer sein, ein Heilmittel für Gifte herzustellen, da nicht selten jedes einzelne ein ganz bestimmtes Gegenmittel erfordert. Stellt Euch vor, man könnte ein Gift durch Willenskraft heilen, ohne dass man sich Gedanken über die exakte Zusammensetzung des Gegenmittels machen müsste!\n\nUnd jetzt lasst mich daran arbeiten!" }, enUS = { progress = "Have you got the reagents I need to make the salve?  The deer aren't getting any better on their own, so we better hurry to help them out!", completion = "This is good, {name}, so much so that it should be enough to make some ample doses of the salve - at least enough to start to make a difference.\n\nMaking a cure for poisons can be quite difficult at times because each one often requires a very specific antidote to counteract it.  Imagine being able to cure a poison at will without having to worry about the exact ingredients of what the antidote must be!\n\nNow, let me get to work on this!" } })
apply(6124, { "classic", "forever" }, { deDE = { completion = "Ihr habt bei der Heilung des kranken Wilds von Dunkelküste wahre Wunder gewirkt. Es war das arglose Opfer einer größeren Besudelung und Verderbnis geworden, die sich über das Land ausbreitete. In Darnassus gibt es welche, die die Bedrohung ernst nehmen... und es gibt welche, die ignorieren die zunehmenden Zeichen... Ich hoffe, Ihr werdet nicht die Augen vor dem Offensichtlichen verschließen, {name}.\n\nWie auch immer, Ihr habt Euren Wert als Freund der Natur und des Zirkels unter Beweis gestellt - nehmt dies als Symbol dafür." }, enUS = { completion = "You have done well in tending to the sickly deer of Darkshore; they are unwitting victims of a greater taint and corruption that is spreading all throughout the land.  There are those in Darnassus who choose to recognize this threat... and there are those who ignore the growing signs.  I hope you will not be one to put blinders on about what facts stare you in the face, {name}.\n\nRegardless, you've proven your worth as a friend of nature and the Circle - take this as a symbol of such." } })
apply(6126, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, junger {class}, ich sehe mit Freuden, dass Ihr begierig seid, etwas über die Heilung von Vergiftungen zu lernen.\n\nFrüher wurden die meisten Druiden vorab geplanten Prüfungen unterzogen, doch das trifft auf Euch nicht zu. Bei Crossroads im Brachland traten vermehrt Fälle von Tiervergiftungen auf, die nicht unter Kontrolle zu bringen sind. Jemand dort bat Moonglade um Hilfe. Wir schicken Euch zu ihrer Unterstützung dorthin. Dies ist keine Übung - es handelt sich um eine echte Aufgabe. Vergesst das nicht." }, enUS = { completion = "Greetings young {class}, I'm glad to see you ready and eager to learn about the curing of poisons.\n\nWhile most druids in the past were put through pre-planned trials, your work will involve no such thing.  There has been a rash of animal poisonings at the Crossroads in the Barrens, and they're unable to bring it under control.  Someone there has requested Moonglade for aid, so we are sending you there to aid them.  This is no exercise - the work you'll do is quite real.  Bear this in mind." } })
apply(6127, { "classic", "forever" }, { deDE = { progress = "Seid Ihr vom Zirkel des Cenarius in Moonglade geschickt worden, ja? Das ist ein Glück für uns! Unsere Bemühungen, den kranken Gazellen im nördlichen Brachland Gleichgewicht zu bringen, haben nichts genutzt. Wir sind für jede Hilfe dankbar.\n\nHabt Ihr die Probe des Wassers, wie Dendrite Starblaze sagte? Er informierte mich, dass Ihr eine besorgen würdet, damit wir gemeinsam ein Heilmittel finden...", completion = "Bei meinen Vorfahren, dieses Wasser ist widerwärtig! Kein Wunder, dass die Gazellen krank sind.\n\nEtwas verunreinigt das Wasser und zerstört damit langsam das Ökosystem im nördlichen Brachland. Überall nördlich der Ost-West-Straße wurden kranke Gazellen gesehen. Das Wasser ist wahrscheinlich der Hauptgrund für die Ausbreitung der Krankheit, aber hier wirkt noch etwas anderes.\n\nDieses Wasser wird uns, ob Ihr es glaubt oder nicht, ein Heilmittel finden helfen. Während ich dieses Wasser untersuche benötige ich einige Zutaten für ein Heilmittel..." }, enUS = { progress = "You are the one that the Cenarion Circle in Moonglade sent, yes?  This is most fortuitous for us!  We are stymied in our effort to bring balance to the sickly gazelles that wander the northern Barrens; we're happy for all the help we can get.\n\nDo you have the sample of water that Dendrite Starblaze said you'd have?  He notified me that you'd draw one so we could work on a cure together...", completion = "By my ancestors, this water is disgusting!  No wonder the gazelles are sick.\n\nSomething is polluting the water, and in turn beginning to wreck the northern Barrens ecosystem.  Sick gazelles have been sighted all north of the east-west road here.  While this water is most likely a primary source of the sickness spreading, there's something else at work here.\n\nThis water, believe it or not, will help us formulate a cure.  While I research this water, I have need of some items to formulate a cure..." } })
apply(6128, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Reagenzien bekommen, die ich für meine Salbe brauche? Die Gazellen werden von allein ganz bestimmt nicht wieder gesund, daher sollten wir nicht zaudern im Bemühen, sie zu retten!", completion = "Das ist gut, {name}, so sehr, dass es für eine gehörige Portion Salbe reichen müsste - wenigstens so viel, dass eine Wirkung zu spüren ist.\n\nManchmal kann es recht schwer sein, ein Heilmittel für Gifte herzustellen, da nicht selten jedes einzelne ein ganz bestimmtes Gegenmittel erfordert. Stellt Euch vor, man könnte ein Gift durch Willenskraft heilen, ohne dass man sich Gedanken über die exakte Zusammensetzung des Gegenmittels machen müsste!\n\nUnd jetzt lasst mich daran arbeiten!" }, enUS = { progress = "Have you got the reagents I need to make the salve?  The gazelle aren't getting any better on their own, so we better not tarry in our effort to save them!", completion = "This is good, {name}, so much so that it should be enough to make some ample doses of the salve - at least enough to start to make a difference.\n\nMaking a cure for poisons can be quite difficult at times because each one often requires a very specific antidote to counteract it.  Imagine being able to cure a poison at will without having to worry about the exact ingredients of what the antidote must be!\n\nNow, let me get to work on this!" } })
apply(6129, { "classic", "forever" }, { deDE = { completion = "Ihr habt bei der Heilung der kranken Gazellen des Brachlands wahre Wunder gewirkt. Sie waren das arglose Opfer einer größeren Besudelung und Verderbnis geworden, die sich über das Land ausbreitete. Ihr {race} brennt darauf, die Wege des Cenarius zu verstehen. Ihr habt, wie Eure Ältesten in Thunder Bluff, den Beweis angetreten, dass die Notwendigkeit des Gleichgewichts künstliche Barrieren zwischen den Völkern überwindet.\n\n{name}, Ihr habt Euren Wert als Freund der Natur und des Zirkels unter Beweis gestellt - nehmt dies als Symbol dafür." }, enUS = { completion = "You have done well in tending to the sickly gazelles of the Barrens; they are unwitting victims of a greater taint and corruption that is spreading all throughout the land.  You {race} are most eager to understand the ways of Cenarius; you, like your elders in Thunder Bluff, are proving that the need for balance transcends artificial racial barriers.\n\n{name}, you've proven your worth as an friend of nature and the Circle - take this as a symbol of such." } })
apply(6132, { "classic", "forever" }, { deDE = { completion = "Meine Schwester Melizza sagte, dass Ihr kommen würdet. Danke, dass Ihr sie aus dieser misslichen Lage befreit habt. Vermutlich steckt sie leider schon wieder in einer neuen." }, enUS = { completion = "My sister Melizza said you'd be coming.  Thanks a lot for getting her out of the jam she was in; it's too bad that she's already probably found herself in a new one!" } })
apply(6133, { "classic", "forever" }, { deDE = { progress = "Lasst mich nicht warten, {class}.", completion = "Ich gehe davon aus, dass Ihr den Lebenslauf nicht gelesen habt. Nicht einmal Ihr würdet etwas so Idiotisches machen..." }, enUS = { progress = "Do not leave me waiting, {class}.", completion = "I trust you did not read the registry. Not even you would do something that idiotic..." } })
apply(6134, { "classic", "forever" }, { deDE = { progress = "Wo ist mein Geisterplasma, {name}?", completion = "Da ist es! Sieht aus, als hättet Ihr auch etwas davon abbekommen. Irgendwie schleimig, hm?\n\nJedenfalls vielen Dank für Eure Mühe, {name}. Dieses Zeug ist ein Vermögen wert... wenn ich die Zentauren überzeugen kann, dass es echt ist!" }, enUS = { progress = "Where's my ghost-o-plasm, {name}?", completion = "There it is!  Looks like you got some of it on you too.  Kinda slimey, eh?\n\nWell, thanks a lot for all the trouble, {name}.  This stuff will be worth a fortune... if I can convince the centaurs what it is!" } })
apply(6135, { "classic", "forever" }, { deDE = { progress = "Ich würde Euch nicht raten, dass Ihr Euch dieser Herausforderung allein stellt, {class}.", completion = "Gut gemacht, Schwachkopf. Ich fertige aus diesem Fell etwas an, das Ihr brauchen könnt." }, enUS = { progress = "I would not recommend that you take on this challenge alone, {class}.", completion = "Excellent work, imbecile. I shall fashion this fur into something you can use." } })
apply(6136, { "classic", "forever" }, { deDE = { completion = "Macht weiter so und ich muss Euch vom Schwachkopf zum Hirnamputierten erster Klasse befördern." }, enUS = { completion = "Keep this up and I may have to promote you from imbecile to mental deficient, first class." } })
apply(6141, { "classic", "forever" }, { deDE = { completion = "Ich habe Kunde erhalten, dass Unterstützung von Osten kommt. Stammen diese Gerüchte vielleicht von Euch? Seid Ihr hierher gekommen, um dem Scharlachroten Bruder bei seinem Kreuzzug zu helfen?\n\nWenn ja, dann hört gut zu..." }, enUS = { completion = "I received word of aid arriving from the east.  Are you the source of these rumors?  Have you come here to help the Scarlet Brother in its crusade?\n\nIf so, then listen close..." } })
apply(6142, { "classic", "forever" }, { deDE = { progress = "Ich kann es kaum erwarten, mit etwas frischem Fleisch der weichschaligen Muschel angeln zu gehen. Habt Ihr mir die 10 Teile gebracht, die ich brauche?", completion = "Perfekt, Mann, genau das hat mir der Hexendoktor gegen meine Kopfschmerzen verschrieben. Er sagt: 'Mai'Lahii - geh angeln. Dann geht es dir besser.'\n\nAlso, mir geht es jetzt schon besser, danke, Mann!" }, enUS = { progress = "I can't wait to go fishing with some fresh soft-shelled clam meat; did you bring me the 10 pieces of it I need?", completion = "Perfect mon, this is just what the witch doctor told me to do for my headache. He says, \"Mai'Lahii - go fish. It'll make you feel better\"\n\nWell, I feel better already, thanks mon!" } })
apply(6143, { "classic", "forever" }, { deDE = { completion = "So süß die Neuigkeit ist, dass die Naga ausgelöscht wurden, mein Herz ist immer noch schwer. Ich werde den Rest meines Lebens danach trachten, sie alle auszurotten.\n\nHier, wie versprochen Eure Belohnung. Eine Kleinigkeit im Vergleich zu der Genugtuung, dass die Naga für ihre abscheuliche Untat an meiner Mannschaft büßen mussten." }, enUS = { completion = "As sweet as it is hearing the news that the naga have been vanquished, my heart still feels empty. For the rest of my life I will be dedicated to having them all killed.\n\nHere mon, your reward as I promised. It's small in comparison to the gratification of knowing the naga fried for their hated act upon my crew." } })
apply(6144, { "classic", "forever" }, { deDE = { completion = "Der oberste Kreuzzügler sitzt wohlbehalten in der Scharlachroten Bastion, während seine Streitkräfte in unser Land einfallen, unsere Gebäude und Denkmäler entweihen und unser Volk ermorden.\n\nDie Dunkle Fürstin hat befohlen, dass ich mich ein für alle Mal um dieses Insekt kümmere. Ihr sollt zum Instrument der Abrechnung mit den Verlassenen werden." }, enUS = { completion = "The Grand Crusader sits safely in the Scarlet Bastion while his forces pour into your lands, desecrate your structures and monuments and murder your people.\n\nThe Dark Lady has commanded that I deal with this insect once and for all. You will become the instrument of the Forsaken's reckoning." } })
apply(6145, { "classic", "forever" }, { deDE = { progress = "Wenn Euch das gelingt, habt Ihr Euch fast meinen Respekt verdient, {class}.", completion = "<Nathanos lacht.>\n\nExzellent! Endlich! Eine Gelegenheit, das Scharlachrote Orakel zu vernichten!" }, enUS = { progress = "Succeed now and you will have almost earned my respect, {class}.", completion = "<Nathanos laughs.>\n\nExcellent! Finally! An opportunity to destroy the Scarlet Oracle!" } })
apply(6146, { "classic", "forever" }, { deDE = { progress = "Das ist nicht akzeptabel, Soldat!", completion = "Wo seid Ihr gewesen? Wir dachten schon, die Geißel hätte Euch erwischt." }, enUS = { progress = "This is unacceptable, soldier!", completion = "Where have you been? We had thought the Scourge had captured you." } })
apply(6147, { "classic", "forever" }, { deDE = { completion = "Diese Narren! Meine Täuschung ist nicht aufgefallen! Macht Euch bereit, {class}. Wir müssen mit kalter List zuschlagen!" }, enUS = { completion = "The fools! My deception went unnoticed! Prepare yourself, {class}. We must strike with cold cunning!" } })
apply(6148, { "classic", "forever" }, { deDE = { completion = "Von diesem Schlag werden sie sich jahrelang nicht erholen! Gut gemacht, {name}! Ihr habt Euch nicht nur meinen Respekt verdient, sondern auch diese Belohnung." }, enUS = { completion = "They will be reeling from this blow for years! Well done, {name}! You have earned not only my respect but also this reward." } })
apply(6161, { "classic", "forever" }, { deDE = { progress = "Diese Truhe ist sicher verschlossen.", completion = "Die Truhe geht auf und gibt Rackmores Schatz preis!" }, enUS = { progress = "This chest is securely locked.", completion = "Chest opens to reveal Rackmore's treasure!" } })
apply(6162, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Kopf der Bestie schon, {name}? Sie wird für ihre Verbrechen büßen. Mir ist egal, ob sie verderbt oder nur wütend ist, weil sie in diesem garstigen Wald hausen muss. Kein Furbolg, der solche Verbrechen an meiner Familie begeht, darf überleben!", completion = "Ihr macht mir Ehre, indem Ihr zu Eurem Wort steht. Mein Mann fiel im Kampf - er wäre stolz darauf gewesen. Aber ich könnte keine Ruhe finden, wenn ich nicht wüsste, dass die Kreatur, die mich zu meinem Witwendasein verdammte, nicht für ihre Tat bezahlt hätte.\n\nNochmals danke, {name}." }, enUS = { progress = "Do you have the beast's claw yet, {name}? It will pay for its crimes. I don't care if it's corrupt or just angry for living in such a dismal forest. No furbolg will live for long committing such crimes against my family!", completion = "You bring honor to me for following through with your word. My husband died in battle--he would have been proud of that. But I could not rest until I knew that the creature that has forced me to live my life alone paid for what it had done.\n\nThank you again, {name}." } })
apply(6163, { "classic", "forever" }, { deDE = { progress = "Als Sylvanas mich befreit hatte, jagte ich die Bestie monatelang durch diese Wüste. Er floh ins sichere Stratholme. Der Bastard...", completion = "Ich frage mich... hat es um Gnade gewinselt? Wusste es überhaupt, was Gnade ist?\n\n<Nathanos spuckt aus.>\n\nIch werde den Kopf dieser Bestie an meine Wand hängen.\n\nIhr habt Euch einen Platz unter meinen Helden verdient, {name}." }, enUS = { progress = "After Sylvanas freed me, I hunted the beast across these wastes for months. It fled to the safety of Stratholme. The bastard...", completion = "I wonder... did it beg for mercy? Could it know what mercy is?\n\n<Nathanos spits.>\n\nI will hang this beast's head upon my wall.\n\nYou have earned a spot amongst one of my champions, {name}." } })
apply(6164, { "classic", "forever" }, { deDE = { progress = "Habt Ihr mein Quittungsbuch? Ich will endlich wieder an die Arbeit gehen!", completion = "Da ist es! Oh meine Güte! Ich hatte vergessen, wie voll es war!\n\nDies ist ein glorreicher Tag, {name}! Toll! Wahnsinnig gut, sage ich Euch!" }, enUS = { progress = "Do you have my receipt book?  I can't wait to get back to business!", completion = "There it is!  And oh my!  I forgot how full it was!\n\nThis is a glorious day, {name}!  Stupendous!  Insanely good, I say!" } })
apply(6181, { "classic", "forever" }, { deDE = { progress = "Ihr seht aus, als hättet Ihr es eilig. Tja, dann seid Ihr hier genau richtig!", completion = "Ihr müsst diese Notiz nach Stormwind bringen? Das ist kein Problem, Ihr könnt einen meiner Greifen nehmen!" }, enUS = { progress = "You look like you're in a hurry.  Well, then you came to the right place!", completion = "You have to get this note to Stormwind?  That's not a problem, you can take one of my gryphons!" } })
apply(6182, { "classic", "forever" }, { deDE = { completion = "Nach einigen Berichten über ungewöhnliche Aktivität der Verlassenen in den östlichen Pestländern wurden Agenten von SI:7 zu Ermittlungen hingeschickt. Die Resultate dieser Ermittlungen sind beunruhigend." }, enUS = { completion = "After some reports of unusual Forsaken activity in the Eastern Plaguelands, SI:7 agents were dispatched to investigate. The results of that investigation are unsettling." } })
apply(6183, { "classic", "forever" }, { deDE = { completion = "<Mathias nickt.>\n\nIch war gewiss, dass Bolvar mir ehrenhafte Männer und Frauen schicken würde - die treuesten Soldaten der Allianz." }, enUS = { completion = "<Mathias nods.>\n\nI had faith that Bolvar would send me men and women of honor - the most dedicated soldiers of the Alliance." } })
apply(6184, { "classic", "forever" }, { deDE = { completion = "Eure erste Mission ist kurz und knapp, {name}. Ihr geht rein, ihr geht raus. Aufklären..." }, enUS = { completion = "The first mission will be straight up, {name}. You go in, you come out. Recon..." } })
apply(6185, { "classic", "forever" }, { deDE = { progress = "G... Glück gehabt???", completion = "Rutger. Fredo. Turyen. Alle... tot...\n\n<Flint umklammert die Insignien.>\n\nWo waren sie? Habt Ihr weitere Informationen über diesen Dreckskerl, diesen Blightcaller, gefunden?" }, enUS = { progress = "An... Any luck??", completion = "Rutger. Fredo. Turyen. All... dead...\n\n<Flint clutches the insignias tightly.>\n\nWhere were they? Did you discover any more information about this bastard, the Blightcaller?" } })
apply(6186, { "classic", "forever" }, { deDE = { completion = "Nein. Es... NEIN! Wie? Ein Agent der Verlassenen? Der HELD der Bansheekönigin???\n\n<Hochlord Bolvar Fordragon sackt geknickt in sich zusammen.>" }, enUS = { completion = "No. It... NO! How? An agent of the Forsaken? The CHAMPION of the Banshee Queen???\n\n<Highlord Bolvar Fordragon slumps in defeat.>" } })
apply(6187, { "classic", "forever" }, { deDE = { completion = "Das ist eine Tragödie. Ich glaube... Ich glaube, unsere Art ist verflucht, {name}. Wir sind verflucht, unsere größten Krieger zu verlieren, unsere edelsten Helden, unsere begabtesten Gelehrten.\n\nWir stehen in Eurer Schuld und ich versichere Euch, {name}, dass Nathanos Marris auf Euch herablächeln wird, wo immer er jetzt sein mag." }, enUS = { completion = "It is a tragedy. I think... I believe that our kind is cursed, {name}. We are cursed to lose our greatest warriors; our most noble heroes; our most gifted scholars.\n\nWe are indebted to you and I assure you, {name}, wherever Nathanos Marris is now, he smiles down upon you." } })
apply(6261, { "classic", "forever" }, { deDE = { progress = "Ist das Schweiß auf Eurer Stirn, der Herr? Ihr habt Euch beim Laufen zu sehr verausgabt. Nehmt nächstes Mal einen Greifen!", completion = "Eine Kiste für Westfall, eh? Seid Ihr schon mal in Westfall gewesen? Falls ja, ist das kein Problem. Ich habe viele Greifen ausgebildet, damit sie diese Route fliegen können!" }, enUS = { progress = "Is that sweat on your brow, lad?  You've been running too much.  Next time, take a gryphon!", completion = "A crate for Westfall, eh?  Have you been to Westfall before?  If so, then it's no problem, my friend.  I have plenty of gryphons trained to fly that route!" } })
apply(6281, { "classic", "forever" }, { deDE = { progress = "Ihr seid gereist, ja? Seid Ihr an irgendwelchen interessanten Orten gewesen?", completion = "Ah, eine Notiz von Quartiermeister Lewis? Es überrascht mich gar nicht, dass er mehr Ausrüstung braucht. Die Späherkuppe ist weit entfernt in einem Land, das Stormwind fast vergessen hat.\n\nIch danke Euch, {name}. Hier habt Ihr etwas Geld für Eure Reisespesen." }, enUS = { progress = "You've been traveling, eh?  Have you been anywhere interesting?", completion = "Ah, a note from Quartermaster Lewis?  I'm not surprised he needs more gear.  Sentinel Hill is far away, in a land Stormwind has all but forgotten.\n\nWell thank you, {name}.  Here's some money to cover your travel costs." } })
apply(6282, { "classic", "forever" }, { deDE = { completion = "Das sind wirklich ganz ausgezeichnete Nachrichten! Erzählt mir noch einmal, wie Ihr in den kalten Herzen dieser schändlichen Harpyien Furcht gesät habt. Die Blutfurien haben einen schweren Schlag erlitten!" }, enUS = { completion = "This is most excellent news! Tell me again how you cast fear into the cold hearts of those vile harpies. The Bloodfuries have been dealt a serious blow!" } })
apply(6283, { "classic", "forever" }, { deDE = { progress = "Die Zerfetzerin der Blutfurien ist ein garstiges Geschöpf! Ihr findet sie bestimmt entlang der westlichen Hügelkette im verbrannten Tal.\n\nDie Blutfurien werden ohne sie hilflos sein... gewiss können wir sie für alle Zeiten loswerden!", completion = "Ich spüre bereits, wie die Wut von mir weicht. Was soll ich mit meiner Zeit anfangen? Das Wissen, dass das Böse um mein Land schleicht, hielt meine Gedanken wach, doch nun sind sie verstummt. Vielleicht ist das ja gut so... vielleicht kann ich mich jetzt auf das Gute konzentrieren, was alle Tauren tun sollten.\n\nBitte nehmt das als Belohnung für Eure Mühe an." }, enUS = { progress = "Bloodfury Ripper is a nasty creature! You will have success finding her along the western hill line in the Charred Vale.\n\nThe bloodfuries will be helpless with out... surely we can vanquish them forever!", completion = "Already I feel the anger leave me. What will I do with my time? Knowing evil moves near my land kept my thoughts moving, though now they are silent. Perhaps this is a good thing... maybe now I can focus on the good, as all Tauren should.\n\nPlease accept this as a reward for your troubles." } })
apply(6284, { "classic", "forever" }, { deDE = { progress = "Besseleth ist ein ruchloses Raubtier... Ich fürchte um alle, die nachts auf dem Weberpass reisen. Dann nämlich lauern sie und ihre Kinder arglosen Reisenden auf. Ich selbst wurde schon Opfer ihres tödlichen Fangzahns, der eine Elle lang ist, aber zum Glück konnte ich sie abwehren und mich in Sicherheit bringen. Ich würde alles dafür geben, wenn dieses Monster vernichtet würde.", completion = "Gute Jagd, {name}! Besseleth ist ein altes Raubtier in dieser Gegend... Ich werde sie nicht vermissen. Nehmt diese Belohnung als Zeichen dafür, dass Ihr der Held des Waldes seid.\n\n\n\nVielleicht werden jetzt viele nach Sonnenfels kommen und sich nicht mehr vor dem fürchten müssen, was in der Dunkelheit lauert." }, enUS = { progress = "Besseleth is a ruthless predator... I fear for those that travel Webwinder Path at night. It's then that she and her children prey upon innocent travelers. I myself fell prey to her two-foot fang of death, but luckily I was able to fend her off and get to safety. I would give anything to see that monster destroyed.", completion = "Good hunting, {name}! Besseleth is an old predator in these parts... I will miss her not. Take this reward as a token for being the forest champion.\n\n\n\nPerhaps now many more will travel to Sun Rock Retreat without fearing what lurks in the dark." } })
apply(6285, { "classic", "forever" }, { deDE = { progress = "Ihr seid aus Stormwind zurück? Hat Osric die Rüstungen geschickt?", completion = "Großartig, Ihr habt die Rüstungen! Wir verteilen sie unverzüglich an alle, die sie brauchen.\n\nDanke, {name}. Ihr wart uns mit Euren Bemühungen eine große Hilfe. Jetzt, da Euch Greife nicht mehr fremd sind, kommt Ihr hoffentlich öfter und helft den Bewohnern der Späherkuppe!" }, enUS = { progress = "You're back from Stormwind?  Did Osric send the armor?", completion = "Great, you brought the armor!  We'll get this divvied to those who need it immediately.\n\nThank you, {name}.  Your efforts have been a great help to us.  And now that you're no stranger to gryphons, I hope you'll come and lend your aid to Sentinel Hill often!" } })
apply(6301, { "classic", "forever" }, { deDE = { progress = "Die ständige Zerstörung durch den Krieg und alle, die mit Holz Profit machen möchten, bekümmert mich zutiefst. Um den Zyklus der Wiedergeburt zu unterstützen und die Länder wieder zu bewalden, benötige ich Gaeasamenkörner. Habt Ihr sie, {class}?", completion = "Ah, {name}, Ihr habt die Gaeasamenkörner. Schaut zu und seht, wie der Segen der Erdenmutter sogar diese kleinen Samenkörner des Lebens blühen und gedeihen lassen kann." }, enUS = { progress = "The continuous destruction caused by war and those that seek a profit from lumber pains me deeply. To aid the cycle of rebirth and replenish the lands, I need Gaea seeds. Do you have them, {class}?", completion = "Ah, {name}, you have the Gaea seeds. Watch and see how the blessing of the Earthmother can cause even these small kernels of life to bloom and flourish." } })
apply(6321, { "classic", "forever" }, { deDE = { progress = "Ihr scheint in einer offiziellen Angelegenheit hier zu sein...", completion = "Ah, eine Anforderungsliste für Vorräte. Die solltet Ihr wohl in die Undercity bringen. Und zwar rasch, denn das Grabmal darf nicht unterversorgt sein." }, enUS = { progress = "You appear to be on official business...", completion = "Ah, an order for supplies.  You will want to take this to the Undercity, no doubt.  And quickly, for the Sepulcher must not be left under stocked." } })
apply(6322, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr weite Strecken reisen müsst, dann ist eine Fledermaus das ideale Transportmittel.", completion = "Diese Kiste muss zum Grabmal im Silberwald? Nichts leichter als das, unsere Fledermäuse fliegen täglich dorthin." }, enUS = { progress = "If you must travel a long distance, then a bat is your best option.", completion = "This crate must reach the Sepulcher in Silverpine?  That is easily done; our bats fly there daily." } })
apply(6323, { "classic", "forever" }, { deDE = { progress = "Ich halte meine Waffen in einem Top-Zustand. Sie sind gereinigt und einsatzbereit.", completion = "Eine Anforderungsliste vom Grabmal? Wohlan denn. Es ist eine Ehre, denen zu dienen, die unserer Dunklen Fürstin dienen." }, enUS = { progress = "I keep my weapons in top condition.  They are cleaned and ready for use.", completion = "An order from the Sepulcher?  Very well.  It is an honor to serve those who serve our Dark Lady." } })
apply(6324, { "classic", "forever" }, { deDE = { progress = "{name}, Ihr kehrt zurück. Habt Ihr unseren Nachschub aus Undercity?", completion = "Gute Arbeit, {name}. Diese Waffen gewährleisten, dass unsere Todeswachen nicht unvorbereitet überrascht werden.\n\nIhr habt der Dunklen Fürstin einen wertvollen Dienst erwiesen." }, enUS = { progress = "{name}, you return.  Do you have our supplies from the Undercity?", completion = "Good work, {name}.  These weapons will ensure our Deathguards don't get caught unprepared.\n\nYou have done a valuable service for our Dark Lady." } })
apply(6341, { "classic", "forever" }, { deDE = { progress = "Wie kann ich Euch helfen? Benötigt Ihr ein Transportmittel?", completion = "Ah, Ihr möchtet, dass dies nach Auberdine gebracht wird? Nun gut..." }, enUS = { progress = "How may I help you?  Are you in need of transport?", completion = "Ah, you wish to get this to Auberdine?  Very well..." } })
apply(6342, { "classic", "forever" }, { deDE = { progress = "Kommt Ihr aus Teldrassil? Erzählt mir, wie angelt es sich dort?", completion = "Ein Päckchen von Nessa? Danke, {name}! Sie sagte mir, sie würde mir Exemplare der Fische schicken, die in der Nähe von Rut'theran gefangen werden. Sie glaubt, die könnten sich von den hiesigen Fischen unterscheiden...\n\nHerrje! Der Kieferknochen ist fast doppelt so groß wie beim gleichen Fisch hier. Und diese Schuppen sind so groß wie eine geballte Faust! Erstaunlich!" }, enUS = { progress = "Have you come from Teldrassil?  Tell me, how is the fishing there?", completion = "A package from Nessa?  Thank you, {name}!  She told me she would send me samples of the fish caught near Rut'theran village.  She thinks they may be very different from the fish caught here...\n\nMy!  This jawbone is nearly twice the size of the same fish found here.  And these scales are as big as a closed fist!  Amazing!" } })
apply(6343, { "classic", "forever" }, { deDE = { progress = "{name}, Ihr seid aus Auberdine zurück? Habt Ihr mit Laird gesprochen?", completion = "Das ist sehr interessant. Die Fische hier sind riesig, aber ich hätte nicht gedacht, dass der Unterschied der Arten zwischen hier und dem Festland so groß ist. Dafür muss es einen Grund geben...\n\nIch danke Euch, {name}. Ich werde die Nachrichten, die Ihr gebracht habt, mit den Dorfbewohnern besprechen. Vielleicht finden wir eines Tages die Ursache dieser Kuriosität. Doch bis dahin wollen wir nutzen, was sie uns beschert!" }, enUS = { progress = "{name}, you're back from Auberdine?  Did you speak with Laird?", completion = "This is very interesting.  The fish here are large, but I didn't think the difference in bounties between here and the mainland was so great.  There must be a reason for this...\n\nWell thank you, {name}.  I will discuss with the villagers the news you brought.  Perhaps, one day, we will find the root of this oddity.  But until then, we shall reap its benefits!" } })
apply(6344, { "classic", "forever" }, { deDE = { completion = "Ja, ich brauche einen Kurier, der ein Päckchen nach Dunkelküste bringt. Werdet Ihr mir helfen?" }, enUS = { completion = "Yes, I have need of a courier who will take a package to Darkshore.  Will you help me?" } })
apply(6361, { "classic", "forever" }, { deDE = { progress = "Seid Ihr wegen eines Windreiters hier? Habt Ihr etwas zu transportieren?", completion = "Wenn Ihr diese Bälge nach Thunder Bluff bringen müsst, dann sprecht Ihr mit dem richtigen Orc!" }, enUS = { progress = "Are you here for a wind rider?  You have something to transport?", completion = "If you must take these hides to Thunder Bluff, then you are speaking to the right orc!" } })
apply(6362, { "classic", "forever" }, { deDE = { progress = "Ihr habt Staub auf den Schultern, der aus dem Brachland sein muss. Habt Ihr mit meinem Freund Jahan gesprochen?", completion = "Ah, ein neues Bündel Bälge. Ich werde mich sofort damit an die Arbeit machen!\n\nDanke, Bruder. Ihr habt mir einen großen Dienst erwiesen. Hier habt Ihr ein paar Münzen für eure Zeit und Reisekosten." }, enUS = { progress = "There is dust on your shoulders that must be from the Barrens.  You have spoken with my friend Jahan?", completion = "Ah, a new bundle of hides.  I will get to work on these immediately!\n\nThank you, brother.  You have done me a great service.  Here are some coins to pay for your time and travel costs." } })
apply(6363, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {class}. Was kann ich für Euch tun?", completion = "Ihr müsst das nach Crossroads bringen, hm? Das ist kein Problem. Wenn Ihr schon einmal dort gewesen seid und mit Devrak gesprochen habt, dann könnt Ihr einen meiner Windreiter zurück zu ihm nehmen." }, enUS = { progress = "Greetings, {class}.  What can I do for you?", completion = "You need to take this to the Crossroads, eh?  That's not a problem.  If you've already been there and spoken to Devrak, then you can take one of my wind riders back to him." } })
apply(6364, { "classic", "forever" }, { deDE = { progress = "{name}, Ihr seid aus Thunder Bluff zurück? Habt Ihr die Bälge zu Ahanu gebracht?", completion = "Ahanu schickt mir fertige Produkte? Sehr gut. In Crossroads wimmelt es gerade von Jägern und Abenteurern und die Geschäfte gehen blendend. Ich bin sicher, ich kann diese Waren im Handumdrehen an den Mann bringen.\n\nVielen Dank für all Eure Bemühungen, {name}. Ich stehe in Eurer Schuld." }, enUS = { progress = "{name}, you are back from Thunder Bluff?  Did you deliver the hides to Ahanu?", completion = "Ahanu sent me finished products?  Very good.  There are many hunters and adventurers in the Crossroads now and business is lively.  I am sure I'll sell these goods very soon.\n\nThank you for all your efforts, {name}.  I am in your debt." } })
apply(6365, { "classic", "forever" }, { deDE = { progress = "Ihr wollt schnell irgendwohin? Tja, dann sprecht Ihr mit dem richtigen {race}!", completion = "Ihr müsst dieses Fleisch nach Orgrimmar bringen? Das ist kein Problem. Für ein bescheidenes Sümmchen kann mein Windreiter Euch hinbringen." }, enUS = { progress = "You need to get somewhere fast?  Then you're talking to the right {race}!", completion = "You have to get this meat to Orgrimmar?  That is no problem.  For a small fee, my wind rider can take you there." } })
apply(6381, { "classic", "forever" }, { deDE = { progress = "Diese Samenkörner, die Ihr pflanzt, sind stark, widersetzen sich der Verderbnis und schaffen neuen Platz für anderes Leben. Sie werden wachsen und wachsen, zuerst die Verderbnis verhindern und das vernarbte Land heilen, und dann werden sie eines Tages das Steinkrallengebirge wieder zu einem üppigen Wald machen.\n\nHabt Ihr alle Gaeasamenkörner gepflanzt?", completion = "Das ist ein großer Sieg für das Land. Mit der Zeit werden auch andere Dinge geschehen: Die Venture Company wird die Kreissägen und Äxte zusammenpacken, die wütenden Feuergeister werden sich beruhigen und die Harpyien werden vom Land vertrieben.\n\nErst dann, {name}, wird das Steinkrallengebirge wirklich Frieden finden.\n\nIhr habt Eure Sache gut gemacht, {class}. Nehmt einen dieser Gegenstände als Dank für das neue Leben, das Ihr heute hier geschaffen habt." }, enUS = { progress = "These seeds you plant are strong, resisting corruption, and making a foothold for other life. They will grow and grow, first preventing corruption and healing the scarred land, and then one day, restoring Stonetalon to a lush forest, once again.\n\nHave you planted all of the Gaea seeds?", completion = "This is great victory for the land. In time, other things will come to pass: the Venture Co. will pack up their buzz saws and axes, the angry fire spirits will calm, and the harpies will be pushed out by the land.\n\nOnly then {name}, will Stonetalon be truly at peace.\n\nYou have done well {class}; take one of these items as thanks for the new life you have created here today." } })
apply(6382, { "classic", "forever" }, { deDE = { completion = "Willkommen an der neuen Grenze, {name}. Ashenvale ist ein Land der unbegrenzten Möglichkeiten, eines, in dem jemand Eurer Art, {class}, jede Menge Gelegenheiten finden wird, seinen Mumm unter Beweis zu stellen. Schaut Euch hier im Außenposten um und begebt Euch auf jeden Fall auch einmal hinaus zum Zoramstrand, denn die Horde hat dort noch einen weiteren Außenposten.\n\nEure Anwesenheit hier sagt mir, dass Ihr gekommen seid, um mehr über die Jagd zu lernen. Hört mir genau zu, und ich werde euch gern mitteilen, was Ihr wissen müsst." }, enUS = { completion = "Welcome to the new frontier, {name}.  Ashenvale is a land of opportunity, one where a young {class} like yourself is able to find boundless chances to prove their mettle.  Look around the outpost here, and be sure to travel out to the Zoram Strand, as the Horde has another outpost there as well.\n\nYour presence here tells me that you've come to learn more about the hunt.  Listen close, and I will gladly share with you what you need to know." } })
apply(6384, { "classic", "forever" }, { deDE = { progress = "Irgendwas riecht lecker! Ihr habt nicht zufällig rohes Fleisch bei Euch, oder?", completion = "Wie wundervoll! Das ist bestes Filet! Es ist von Zargh, richtig? Dieser {race} versteht es, das Herz einer Dame zu betören...\n\nOh, ich kann es kaum erwarten, das zuzubereiten. Aber nicht zu viel! Fleisch serviert man am besten selten, findet Ihr nicht auch?" }, enUS = { progress = "Something smells good!  You don't have raw meat on you, do you?", completion = "Oh, wonderful!  Those are fine cuts!  These are from Zargh, are they?  That {race} sure knows his way into a lady's heart...\n\nOh, I can't wait to cook it.  But not too much!  Meat is best served rare, don't you think?" } })
apply(6385, { "classic", "forever" }, { deDE = { progress = "Braucht Ihr einen meiner Windreiter?", completion = "Ihr müsst das nach Crossroads im Brachland bringen? Ja, ich kann Euch dorthin bringen..." }, enUS = { progress = "Do you need one of my wind riders?", completion = "You have to get this to the Crossroads in the Barrens?  Yes, I can get you there..." } })
apply(6386, { "classic", "forever" }, { deDE = { progress = "Seid Ihr von Orgrimmar zurück? Hat Gryshka das Fleisch geschmeckt, das ich ihr geschickt habe?", completion = "Ha! Natürlich hat es ihr geschmeckt! Nichts macht die Wangen einer Dame so rot wie ein großes, saftiges Steak!\n\nDanke, {name}. Ihr habt mir einen großen Dienst erwiesen. Hier habt Ihr etwas Geld für Eure Mühe, und seid nicht überrascht, wenn ich Euch zu meiner Hochzeit einlade!" }, enUS = { progress = "Have you returned from Orgrimmar?  Did Gryshka like the meat I sent her?", completion = "Hah!  I guess she liked it!  Nothing brings red to a lady's cheeks like a big, juicy steak!\n\nThank you, {name}.  You've done me a great service.  Here is some money for your trouble, and don't be surprised if I invite you to my wedding!" } })
apply(6387, { "classic", "forever" }, { deDE = { progress = "Habt Ihr schon so bald die Nase voll von Thelsamar? Seid Ihr bereit, in eine andere Stadt abzureisen?", completion = "Ihr müsst das nach Ironforge bringen, hm? Für ein geringes Entgelt setze ich Euch auf den Rücken eines meiner Greife, der Euch dorthin bringt. Na, was sagt Ihr dazu?" }, enUS = { progress = "Have you had your fill of Thelsamar so soon?  Are you ready to leave for another city?", completion = "You have to get this to Ironforge, eh?  For a small fee I can put you on the back of one of my gryphons, and it'll take you there.  How does that sound?" } })
apply(6388, { "classic", "forever" }, { deDE = { progress = "Ihr seht aus, als müsstet Ihr irgendwohin. Braucht Ihr einen meiner Greifen?", completion = "Ihr müsst das nach Thelsamar bringen, hm? Das wird gar kein Problem sein. Wenn Ihr schon in Thelsamar gewesen seid und mit Thorgrum Borrelson gesprochen habt, dann könnt Ihr einen meiner Greifen zurück zu ihm nehmen." }, enUS = { progress = "You look like you have somewhere to go.  Need one of my gryphons?", completion = "You have to get these to Thelsamar, eh?  That won't be a problem.  As long as you've already been to Thelsamar and spoken to Thorgrum Borrelson, then you can take one of my gryphons back to him." } })
apply(6389, { "classic", "forever" }, { deDE = { progress = "Habt Ihr es geschafft, {name}? Habt Ihr die Termiten freigelassen? Das Licht stehe uns bei, wenn der Scharlachrote Kreuzzug sowohl das Werk wie auch Hearthglen halten könnte. Beides hätte nicht gelingen sollen. Sie beuten lediglich die Opfer des letzten Kriegs aus und sollten erlegt werden wie tollwütige Tiere!", completion = "Haha! Danke, {name}! Ihr habt es geschafft! Meines Vaters Geist findet jetzt Ruhe und ich kann in Frieden leben.\n\nNochmals danke. Wenn ich etwas für Euch tun kann, so sagt es bitte." }, enUS = { progress = "Have you done it, {name}? Have you released the termites? The Light help us if the Scarlet Crusade were able to hold onto both the mill and Hearthglen. They should have neither. They're just capitalizing on the victims of the last war and should be put down like rabid animals!", completion = "Haha! Thank you, {name}! You've done it! My father's spirit can now rest and I can live in peace.\n\nThank you again. If there is anything I can do for you, please, just ask." } })
apply(6390, { "classic", "forever" }, { deDE = { progress = "Habt Ihr es geschafft, {name}? Habt Ihr die Termiten im Sägewerk freigelassen?\n\nEs war schlimm genug, dass meine Familie Arbeit und Leben verlor, aber dann mit anzusehen, wie der Ort, wo ich meine Kindheit verbrachte, von diesen widerwärtigen sogenannten heiligen Männern übernommen wurde ... bäh!!!", completion = "Danke, {name}. Hier, nehmt diese Münze. Leider habe ich nicht mehr, aber freut Euch wenigstens darüber, dass Ihr die Bemühungen des Scharlachroten Kreuzzugs durchkreuzt habt!" }, enUS = { progress = "Have you done it, {name}? Have you released the termites in the lumber mill?\n\nIt was bad enough that my family lost their jobs and lives, but then to see the place where my childhood was spent taken over by those disgusting so-called holy men... pfah!!", completion = "Thank you, {name}. Here, take this coin. I'm sorry it's not more, but try to take some joy in helping destroy the Scarlet Crusade's efforts!" } })
apply(6391, { "classic", "forever" }, { deDE = { progress = "Womit kann ich Euch dienen, werter Herr?", completion = "Ah, die neueste Liste von Brocks Meisterschülern. Ich habe schon ein paar Ehrenhacken bereit. Ich muss nur noch die Namen der Studenten eingravieren..." }, enUS = { progress = "What can I do for you, sir?", completion = "Ah, the lastest list of Brock's best pupils.  I have a batch of honorary picks ready to go.  I just need to chisel in the names of the students..." } })
apply(6392, { "classic", "forever" }, { deDE = { progress = "Ah, {name}. Ihr seid aus Ironforge zurück.", completion = "Ihr habt die Hacken. Großartig! Ich werde sie meinen Bergbaustudenten bringen. Sie können es sicher kaum erwarten, sich damit auf die Erzvorkommen von Loch Modan zu stürzen.\n\nDanke für Eure Hilfe, {name}. Ich stehe in Eurer Schuld, hoffe jedoch, dieses Geld wird wenigstens Eure Reisekosten decken." }, enUS = { progress = "Ah, {name}.  Have you returned from Ironforge?", completion = "You brought the picks.  Great!  I'll get these to my mining students.  I'm sure they're eager to use them on the ore deposits of Loch Modan.\n\nThank you for your help, {name}.  I am in your debt, but I hope this money will at least cover your travel costs." } })
apply(6393, { "classic", "forever" }, { deDE = { progress = "Das Tribunal der Gezeiten wird ungeduldig. Es will diesen Krieg beenden, der seit Äonen durch alle Dimensionen wütet. Meine Brüder brennen darauf, dass man ihnen endlich den ruhmreichen Sieg über die verhassten Feuerelementare meldet. Habt Ihr die Pyrophore, die ich benötige?", completion = "Die Wassergeister in mir prickeln vor Aufregung. {name}, durch Euren Einsatz kann ich dem Tribunal der Gezeiten nun einen glorreichen Sieg vermelden." }, enUS = { progress = "The Tribunal of the Tides grows impatient. They seek to end this war that has raged across all dimensions for eons. My brethren are anxious to hear news of the glorious victory over the hated fire elementals. Have you the Incendrites that I require?", completion = "The water spirits within me bubble with the excitement. {name}, you have given me a glorious victory to report to the Tribunal of the Tides." } })
apply(6394, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Koven der Burning Blade betreten, {name}? Und habt Ihr meine Hacke gefunden?", completion = "Prima, Ihr habt sie! Vielen Dank, {name}. Das ist meine Lieblingshacke! Wenn meine Peons irgendwann einmal fertig sind, diese Bäume zu fällen, finden wir vielleicht eine hübsche Höhle für den Bergbau!" }, enUS = { progress = "Have you entered the Burning Blade Coven, {name}?  Did you find my pick?", completion = "Great, you got it!  Thanks a lot, {name}.  This is my favorite pick!  Now if my peons ever finish chopping down these trees, maybe we can find a nice cave to mine!" } })
apply(6395, { "classic", "forever" }, { deDE = { progress = "Wir müssen unsere Toten achten, {name}. Darin unterscheiden wir uns von der Geißel...", completion = "Ihr habt heute eine gute Tat vollbracht, {name}. Der Kampf gegen die Geißel geht zwar weiter, aber hoffen wir, dass Marla und Samuel gemeinsam Frieden in ihrer letzten Ruhestätte finden." }, enUS = { progress = "We must respect our dead, {name}.  It is one of the ways in which we differ from the Scourge...", completion = "You have done a good deed today, {name}.  Although our struggle against the Scourge continues, let us hope that Marla and Samuel will find peace together in their final resting place." } })
apply(6401, { "classic", "forever" }, { deDE = { completion = "Dem Himmel sei Dank, meine Nichte Kaya lebt! Das sind wahrlich gute Neuigkeiten. Danke, {name}." }, enUS = { completion = "My goodness, my niece Kaya is alive! That is good news indeed. Thank you, {name}." } })
apply(6403, { "classic", "forever" }, { deDE = { progress = "Ich... Ich... Ich war machtlos.", completion = "<Bolvar hält das zertrümmerte Medaillon in den Händen.>\n\nDie Magie darin muss wieder entfacht werden. Das Großdrachenauge muss eingestellt werden.\n\nWindsors Opfer hat unser Königreich befreit, aber die Bedrohung durch Onyxia und ihresgleichen besteht immer noch.\n\nDieses Medaillon hielt meinen Geist und meinen Körper gefangen. Es ließ mich jedoch auch in Onyxias Geist blicken - zeigte mir ihre Geheimnisse. Die Visionen sind zwar jetzt etwas verschwommen, aber an manche Dinge erinnere ich mich doch." }, enUS = { progress = "I... I... I was powerless.", completion = "<Bolvar holds the shattered medallion.>\n\nThe magic held within must be reignited. The dragon's eye must be attuned.\n\nWindsor's sacrifice has freed our Kingdom, but the threat of Onyxia and her kin is ever looming.\n\nThis medallion is what held my mind and body captive. It is also what gave me access to Onyxia's own mind - to her secrets. Albeit the visions are muddled now, some things I do remember." } })
apply(6441, { "classic", "forever" }, { deDE = { progress = "Ich hoffe, Ihr könnt mir bald ein paar dieser Hörner besorgen, {name}. Ich muss in Kürze nach Ratchet zurück!", completion = "Die sind perfekt, {name}! Danke, dass Ihr mir geholfen habt!\n\nOh, und das hier ist für Eure Mühen..." }, enUS = { progress = "I hope you can be quick about getting those horns, {name}. I'm heading back to Ratchet soon!", completion = "These are perfect, {name}! Thanks for helping me out!\n\nOh, and this is for your time..." } })
apply(6442, { "classic", "forever" }, { deDE = { progress = "Die Naga werden immer mehr, {name}. Bitte erledigt diese Aufgabe für mich.", completion = "Wir könnten mehr Eures Schlags hier brauchen, {name}. Danke für Eure Hilfe." }, enUS = { progress = "The naga increase in numbers, {name}. Please complete this task for me.", completion = "We could use more of your kind around here, {name}. Thank you for your help." } })
apply(6461, { "classic", "forever" }, { deDE = { completion = "Toll! Gute Neuigkeiten: Vielleicht haben wir heute Nacht ein paar ungebetene Tafelgäste weniger.\n\nVielen Dank, {name}. Wir stehen für immer in Eurer Schuld." }, enUS = { completion = "Sweet, mon! Good news, perhaps we will have fewer unwanted dinner guests tonight.\n\nMany thanks, {name}.  We are forever in your debt." } })
apply(6462, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Glücksbringer gefunden, {name}? Jede Sekunde, die die Furbolgs im Besitz dieser heiligen Gegenstände sind, bringt mein Blut mehr zum Kochen!", completion = "Ihr habt sie gefunden! Danke! Danke, {name}! Ihr wisst ja gar nicht, welch großen Dienst Ihr mir erwiesen habt.\n\nEin Troll ohne Glücksbringer ist wie ein Orc ohne Kampfnarben...\n\nWertlos." }, enUS = { progress = "Did you find the charms, {name}?  Every moment the furbolgs possess those sacred items, my blood boils with rage!", completion = "You found them!  Thank you!  Thank you, {name}!  You do not know how great a thing you have done for me.\n\nA troll without his charm is like an orc without his battle scars...\n\nWorthless." } })
apply(6481, { "classic", "forever" }, { deDE = { completion = "Das sind gute Neuigkeiten, {class}! Ich fürchte mich vor dem, was ein Irdener in Kalimdor anrichten könnte.\n\nGoggeroc zu töten war eine Tat, die eines Helden würdig ist. Das habt Ihr gut gemacht. Die Bewohner des Steinkrallengebirges und Kalimdors stehen in Eurer Schuld, {class}.\n\nNehmt dies als Belohnung, oh Ehrwürdiger." }, enUS = { completion = "You bear good news, {class}! I fear the possibilities of what an Earthen would mean to Kalimdor.\n\nSlaying Goggeroc was a task for no one less than a hero. You have done well; all of Stonetalon and Kalimdor are indebted to you, noble {class}.\n\nAccept this as your reward most honored one." } })
apply(6482, { "classic", "forever" }, { deDE = { completion = "Ihr habt meinen Bruder gefunden! Er wurde vom Distelfellstamm gefangen? Das ist ja schrecklich, denn viele Furbolgs sind zwar edle Kreaturen, aber die Distelfelle sind verderbt.\n\nVielen Dank, dass Ihr meinen Bruder gerettet habt, {name}. Ich wage gar nicht darüber nachzudenken, wie sie den armen Ruul wohl behandelt haben. Er wird nach diesem Martyrium bestimmt eine ganze Weile schlafen ..." }, enUS = { completion = "You found my brother!  He was captured by the Thistlefurs?  That is terrible news to hear, for although many Furbolgs are noble creatures, the Thistlefurs are corrupt.\n\nThank you for rescuing my brother, {name}.  I do not want to think of how they treated poor Ruul.  He will likely sleep long after this ordeal..." } })
apply(6501, { "classic", "forever" }, { deDE = { progress = "Ich spüre eine Aura des Bösen, die von Euch ausgeht, {race}. Was könntet Ihr besitzen, das eine solche Aura ausstrahlt?", completion = "Ich hätte es wissen müssen... ein Stück der schwarzen Großdrachenbrutmutter Onyxia. Wie widerlich..." }, enUS = { progress = "I sense an aura of evil radiating from you, {race}. What could you hold that emits such an aura?", completion = "I should have known - a piece of the black dragon brood mother, Onyxia. How revolting..." } })
apply(6502, { "classic", "forever" }, { deDE = { progress = "Der Fluss der Zeit hält niemals an oder wird auch nur um etwas langsamer, {race}. Mein Leben dauert ewig, Eures jedoch nicht. Vergeudet die Zeit nicht, die Euch noch bleibt...", completion = "Dieses Amulett gewährt Euch den Zugang, auf den Ihr aus seid. Onyxias Hort befindet sich in den Marschen von Dustwallow. Solange Ihr das Amulett habt, können ihre Zauberschütze Euch nicht am Eintreten hindern.\n\nDer blaue Drachenschwarm wünscht Euch Glück, {name}." }, enUS = { progress = "The flow of time does not stop or slow, {race}. While my life is eternal, yours is not. Waste not the time that you have...", completion = "This amulet will grant you the access that you seek. The lair of Onyxia can be found in Dustwallow Marsh. As long as you hold the amulet, her wards cannot prevent you from entering.\n\nThe Blue Flight wishes you luck, {name}." } })
apply(6503, { "classic", "forever" }, { deDE = { completion = "Sehr gut, {name}. Eure Jagdkünste sind beeindruckend...\n\nDer Verlust dieser Kundschafter wird helfen, die Allianz ihrer Augen zu berauben, und wenn sie keine Informationen mehr bekommt, wird sie wohl kaum weiter angreifen." }, enUS = { completion = "Very good, {name}.  Your hunting skills are impressive...\n\nThe loss of those outrunners helps blind the Alliance, and when they lack intelligence they are less likely to launch attacks." } })
apply(6504, { "classic", "forever" }, { deDE = { progress = "Hoffentlich findet Ihr die Seiten bald, {name}! Ich muss wirklich wieder zurück an die Arbeit!", completion = "Lesen ist nicht gerade meine Stärke... aber jetzt kann ich endlich wieder zurück an die Arbeit! Danke, {name}!" }, enUS = { progress = "I hope you find the pages soon, {name}! I really need to get back to work!", completion = "Reading isn't my strong point... but now I'll be able to get back to work! Thanks, {name}!" } })
apply(6521, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Botschafter gefunden, {name}? Ist er tot?\n\nWir können es uns nicht leisten, dass die Geißel in Kalimdor Fuß fasst. Sie ist bereits schon gefährlich genug für unsere eigenen Grenzen, ein Zweifrontenkrieg wäre zu gefährlich.\n\nDas einzig Positive an den Ereignissen, von denen Ihr mir erzähltet, ist, dass die Greisin nicht verderbt zu sein scheint. Sie muss tief in ihrem Herzen wissen, dass die Geißel große Macht bringen kann, dass das Brachland jedoch nicht wirklich ihr gehören würde, wenn sie sich auf den Handel einließe.", completion = "Gut. Gut gemacht, {class}.\n\nDa Malcin jetzt tot ist, wissen wir zumindest, dass der Vormarsch der Geißel aufgehalten wird. Die Dunkle Fürstin dankt Euch für Eure Bemühungen und möchte Euch zur Belohnung ein Geschenk machen.\n\nWir wissen zwar nicht, wie groß der Einfluss der Geißel in den Hügeln ist, aber wir werden bestimmt schon bald einiges über ihre Pläne herausfinden." }, enUS = { progress = "Have you found the Ambassador, {name}? Is he dead?\n\nWe cannot afford to allow the Scourge to take a foothold on Kalimdor. They are enough of a threat to our own borders to have to deal with them on two fronts.\n\nThe only optimistic sign from the events you've told me about is that the crone seemed uncorrupted. She must know deep in her spirit that the Scourge may bring great power, but that the Barrens would not truly be hers if she were to agree to their deal.", completion = "Good. Well done, {class}.\n\nNow that Malcin is dead, we can at least know that the Scourges advances will be halted. The Dark Lady thanks you for your efforts and wishes to reward you with a gift.\n\nAlthough we do not know the extent of the Scourges influence within the Downs, I am sure we will discover their plots soon enough." } })
apply(6522, { "classic", "forever" }, { deDE = { progress = "Worüber wollt Ihr mit mir sprechen, {name}? Es muss wohl wichtig für Euch sein, wenn Ihr mich ständig belästigt.", completion = "Ich erkenne die Insignien auf dieser Rolle, {name}. Ihr habt dies bei der Greisin gefunden, die über den Kral von Razorfen herrscht? Interessant.\n\nDie Geißel scheint sich also offenbar nicht mit einem Kontinent zufrieden zu geben. Dieser Botschafter Malcin - der diese Notiz geschrieben hat - ist einer der von der Geißel verseucht wurde. Er war ein menschlicher Diplomat des Königreichs Lordaeron, bevor sich alles ... verändert hat.\n\nFalls die Geißel versucht, in Kalimdor Fuß zu fassen, liegt es an uns zu handeln." }, enUS = { progress = "What business is it you wish to speak of, {name}? You must feel it is important if you continue to pester me.", completion = "I recognize the insignia on this scroll, {name}. You found this on that crone who reigns over Razorfen Kraul? Interesting.\n\nThe Scourge aren't content with one continent it seems. This Ambassador Malcin--the one who wrote the note--is one of the Scourge's plagued servants, a human diplomat to the kingdom of Lordaeron before things... changed.\n\nIf the Scourge are trying to gain a foothold in Kalimdor, then it is up to us to act." } })
apply(6523, { "classic", "forever" }, { deDE = { completion = "Kaya lebt! Ich habe Euch für ihre Rettung zu danken, {name}." }, enUS = { completion = "Kaya is alive! {name}, I have you to thank for rescuing her." } })
apply(6541, { "classic", "forever" }, { deDE = { completion = "Ashenvale ist ein geteiltes Land, aber unsere jüngsten Bemühungen waren sehr erfolgreich. Wir haben jetzt nicht nur einen Außenposten am Zoramstrand, sondern noch einen weiteren nördlich von hier. Er heißt Splintertree." }, enUS = { completion = "Ashenvale is a divided land, but our most recent efforts have been very successful. We not only have an outpost at the Zoram Strand, but another just north of here called Splintertree." } })
apply(6542, { "classic", "forever" }, { deDE = { completion = "Ashenvale ist ein geteiltes Land, aber unsere jüngsten Bemühungen waren sehr erfolgreich. Wir haben jetzt nicht nur einen Außenposten am Zoramstrand, sondern noch einen weiteren nördlich von hier. Er heißt Splintertree." }, enUS = { completion = "Ashenvale is a divided land, but our most recent efforts have been very successful. We not only have an outpost at the Zoram Strand, but another just north of here called Splintertree." } })
apply(6543, { "classic", "forever" }, { deDE = { progress = "Beeilt Euch, {name}. Sie müssen die Berichte erhalten, es ist wichtig.", completion = "Wie ich sehe, kann ich auf Euch zählen. Diese Neuigkeiten sind unerlässlich für unsere Pläne, unsere Position in Ashenvale zu festigen. Jetzt können wir unseren nächsten Schritt planen." }, enUS = { progress = "Hurry, {name}. They must receive their reports; it is urgent.", completion = "I can see that you are one that can be counted on. These updates are crucial to our plans to further our presence in Ashenvale. We can now plan our next move." } })
apply(6544, { "classic", "forever" }, { deDE = { completion = "Toreks Angriff war also erfolgreich! Gut gemacht, {name}. Nachtelfen sind angemessene Feinde. Ein bisschen mager zwar, aber stark und wild! Die Schlacht war bestimmt eine Augenweide...\n\nUnd ich hoffe, Ihr habt Euch ein paar Narben verdient!" }, enUS = { completion = "So Torek's attack was successful!  Well done, {name}.  Night elves are decent foes.  A little skinny, but strong and fierce!  I'm sure the battle was something to see...\n\nAnd I hope you gained a scar or two!" } })
apply(6548, { "classic", "forever" }, { deDE = { progress = "Habt Ihr sie schon getötet?", completion = "Ich danke Euch, {name}... aber ich werde niemals vergessen, was die Grimmtotem meinem Dorf angetan haben." }, enUS = { progress = "Have you killed them yet?", completion = "{name}, I thank you... but I will never forget what the Grimtotem have done to my village." } })
apply(6561, { "classic", "forever" }, { deDE = { progress = "Möge die Erdenmutter mit Euch sein, {name}.\n\nUnser Ziel sollte Friede auf der Erde sein und unter denen, die sie bewohnen. Sie hat große Pläne mit der Natur und wir alle müssen unsere Rolle in diesem Plan spielen.", completion = "Kelris hat sich der Argentumdämmerung eine ganze Weile entzogen.\n\nEine Zeit lang galt er sogar als tot oder vermisst.\n\nIndem Ihr seinem Regime ein Ende gemacht habt, habt Ihr die Leben vieler Unschuldiger gerettet, {name}.\n\nGelobt sei die Erdenmutter! Jemanden einem Diener eines Alten Gottes zu opfern, um persönlich davon zu profitieren, ist mehr als verachtenswert!\n\nHeute habt Ihr etwas Großes geleistet! Kelris war eine Kreatur des Bösen und trachtete danach, die Welt wieder in eine Zeit des Chaos zu stürzen, indem er einem der alten Götter huldigte. Danke, {name}." }, enUS = { progress = "May the Earthmother be with you, {name}.\n\nPeace between the earth and all her people should be our goal. She has a grand plan for nature, and we all have a role to play in that plan.", completion = "Kelris has eluded the Argent Dawn for some time.\n\nFor some time they considered him dead or missing.\n\nBy ending his reign you have spared the lives of many innocent people, {name}.\n\nEarthmother be praised! To sacrifice another to a servant of an Old God for personal gain is beyond disgusting!\n\nYou have done a great thing this day. Kelris was a creature of evil and sought to bring the world back to a time of chaos by worshipping such creatures as the Old Gods. Thank you, {name}." } })
apply(6562, { "classic", "forever" }, { deDE = { completion = "Tsunaman schickt Euch? Ausgezeichnet. Dann haben wir einiges zu besprechen." }, enUS = { completion = "Tsunaman sent you? Excellent. Then we have matters to discuss." } })
apply(6563, { "classic", "forever" }, { deDE = { progress = "Wie läuft Eure Suche nach den Kristallen, {name}? Habt Ihr die Naga beim Abbau der Steine gesehen? Ich bete zu meinen Vorfahren, dass wir den Grund dafür herausfinden, warum sie diese Dinge sammeln.", completion = "Gut gemacht, {name}. Das sind die Kristalle, von denen ich sprach. Faszinierend...\n\nIch kann die Macht in ihnen spüren. Die Geister des Wassers hängen an ihnen. Was immer die Naga mit ihnen vorhatten... tja, seien wir nur froh, dass sie nicht mehr in ihren Händen sind." }, enUS = { progress = "How goes your search for the crystals, {name}? Have you witnessed the naga harvesting them? I pray to my ancestors we find the reason they are collecting such things.", completion = "Well done, {name}. These are the crystals I spoke of. Intriguing...\n\nI can feel the power within them. The spirits of water cling to them. Whatever the naga were going to use these for... well, let us be glad they are no longer in their hands." } })
apply(6564, { "classic", "forever" }, { deDE = { progress = "Ja, {name}? Was ist Euer Begehr? Ich muss noch so viel über die Kristalle lernen, die die Naga zusammentragen.", completion = "Das ist in der Tat interessant. Ich bin froh, dass Ihr mich davon in Kenntnis gesetzt habt.\n\nJetzt können wir unseren Problemen auch einen Namen geben... Lorgus Jett." }, enUS = { progress = "Yes, {name}? What is it you need? There is still much I must learn about the crystals the naga are gathering.", completion = "This is interesting indeed. I am glad you have brought it to my attention.\n\nNow we have a name for our troubles... Lorgus Jett." } })
apply(6565, { "classic", "forever" }, { deDE = { completion = "Sehr gut! Danke, {name}. Wir mögen zwar die Twilight-Hammer nicht vollständig aufgehalten haben, aber zumindest habt Ihr einen weiteren ihrer Pläne durchkreuzt, die Alten Götter wieder mächtig zu machen.\n\nWer weiß, welche Pläne sie sonst noch verfolgen mochten, aber wir können vorerst beruhigt sein." }, enUS = { completion = "Very good!! Thank you, {name}. We may not have stopped the Twilight's Hammer completely, but at least you have staved off another of their plans to return the Old Gods to power.\n\nWho knows what other plans they have manifesting, but we can rest easy for now." } })
apply(6566, { "classic", "forever" }, { deDE = { progress = "Geduld, {name}. Passt gut auf!", completion = "Seid Ihr bereit, diese Aufgabe anzunehmen?" }, enUS = { progress = "Patience, {name}. Pay attention!", completion = "Are you prepared to take on this task?" } })
apply(6567, { "classic", "forever" }, { deDE = { completion = "Es gibt nur einen Weg in den Hort des Großdrachen, {race}.\n\nWisst Ihr, nur die Stärksten des schwarzen Drachenschwarms dürfen den Hort der Brutmutter betreten. Es müssen viele Prüfungen überwunden werden und der Schlüssel, mit dem man hineingelangt, wurde von General Drakkisath persönlich zeremoniell verzaubert!\n\nDa Ihr nicht zu den schwarzen Großdrachen gehört, werdet Ihr wohl auf einige Schwierigkeiten stoßen, wenn Ihr Einlass verlangt." }, enUS = { completion = "There is but one way into the dragon's lair, {race}.\n\nYou see, only the strongest of the Black Dragonflight are allowed entry into the lair of the brood mother. Many trials must be passed and the key to enter ceremoniously enchanted by General Drakkisath himself!\n\nSince you are not of black dragonkin, you may have some difficulty in obtaining passage." } })
apply(6568, { "classic", "forever" }, { deDE = { progress = "In diesem Teil Lordaerons sieht man nur selten einen aus der Horde. Was habt Ihr für Myranda?", completion = "<Myranda hält die Notiz, schweigt eine Weile, dann lächelt sie.>\n\nWie geht es ihm? Rexxar, meine ich. Oh, bitte, schaut nicht so überrascht drein. Der Brief besteht absichtlich nur aus einem leeren Blatt. Er trägt die Absichten und Gedanken des Schreibers. Angesichts des Inhalts ist es kein Wunder, dass Rexxar so verfahren ist. Stellt Euch vor, man hätte Euch gefangen oder getötet und diese Informationen entdeckt!\n\nAch, wie dem auch sei! Myranda wird Euch helfen, {race}. Ich schulde dem Kriegshäuptling noch einen oder zwei Gefallen." }, enUS = { progress = "It is not often I see one of the Horde in these parts of Lordaeron. What is it that you have for Myranda?", completion = "<Myranda holds the note, pauses, then smiles.>\n\nHow is he? Rexxar, I mean. Oh, come now, do not look so confused. The letter was left intentionally blank. It carried with it the intentions and thoughts of its creator. Judging from its contents, it is no wonder Rexxar left it as such. Imagine if you were captured or slain and this information discovered!\n\nOh, nevermind! Myranda will help you, {race}. I owe the Warchief a favor or two." } })
apply(6569, { "classic", "forever" }, { deDE = { progress = "Die Augen derer, die wir verkörpern möchten, sind die wichtigste Zutat für jede Illusion, {name}.", completion = "Lasst Myranda mal sehen, {race}.\n\nAh ja, ausgezeichnet.\n\nAus diesen Reagenzien wird Myranda ein Medaillon für Euch fertigen, mit dem Ihr eine Illusion erzeugen könnt, die den Torhüter des schwarzen Drachenschwarms täuschen wird." }, enUS = { progress = "The eyes of that which we wish to mimic are the most important ingredient of any illusion, {name}.", completion = "Let Myranda have a look, {race}.\n\nOh yes, these will do nicely.\n\nWith these reagents, Myranda will create for you a medallion that will grant an illusion capable of fooling the black dragonflight's gatekeeper." } })
apply(6571, { "classic", "forever" }, { deDE = { progress = "Hoffentlich kommt Ihr mit dem Nachschub durch!", completion = "Exzellent, {name}. Ihr habt mir eine Menge Arbeit erspart!\n\nAber glaubt nicht, dass ich mich nicht erkenntlich zeige!" }, enUS = { progress = "I hope you can come through with the supplies! I'm in big trouble if I don't deliver them soon!", completion = "Excellent, {name}. You've saved me a lot of work!\n\nBut don't think that I'm not grateful!" } })
apply(6582, { "classic", "forever" }, { deDE = { progress = "<Aschenschwinge faucht.>", completion = "Eine von etlichen Prüfungen überssstanden..." }, enUS = { progress = "<Emberstrife hisses.>", completion = "One of ssseveral complete..." } })
apply(6583, { "classic", "forever" }, { deDE = { progress = "Kommt erst wieder, wenn Ihr im Blut unserer Feinde gebadet und Euch an ihrem Leiden gelabt habt.", completion = "Eine weitere bestanden..." }, enUS = { progress = "Do not return here until you have bathed in the blood of our enemies and drank in their suffering.", completion = "Another complete..." } })
apply(6584, { "classic", "forever" }, { deDE = { progress = "Ironischerweissse ist hier die Zzzeit entscheidend, Welpe.", completion = "Der am meisssten Verhasssssste fehlt Euch noch..." }, enUS = { progress = "Ironically, whelp, time is of the essencccce.", completion = "The most hated remainsss..." } })
apply(6585, { "classic", "forever" }, { deDE = { progress = "Veränderungen... Ich spüre sie schon in Euch, Welpe. Besteht diese Prüfung, dann wartet nur noch eine Zeremonie auf Euch.", completion = "Ich habe mich in Eurem Engagement getäuscht, Welpe. Ihr wart beharrlich, habt unsere Feinde bezwungen und unserem Klan Ehre gemacht.\n\nJetzt muss ich die Schädel für Euren Aufstieg vorbereiten." }, enUS = { progress = "Changesss... I sense them taking place in you, whelp. Pass this test and only ceremony remains.", completion = "I had doubted your dedication, whelp. You persisted, dominating our enemies, bringing honor to our flight.\n\nI must now prepare the skulls for your ascension." } })
apply(6601, { "classic", "forever" }, { deDE = { progress = "Keine Panik, {name}!", completion = "Das ist reines Drachengeschwätz, {name} - viel heiße Luft und keine greifbaren Informationen. Was soll man von ihnen auch anderes erwarten als aufgeblasenes, aggressives Verhalten." }, enUS = { progress = "Do not panic, {name}!", completion = "It is merely dragon-talk, {name} - more hot air than actual substantive information. Pompous, aggressive behavior is to be expected from their kind." } })
apply(6602, { "classic", "forever" }, { deDE = { progress = "Man darf Drakkisath nicht unterschätzen, {name}. Er hat den Tod von Tausenden auf dem Gewissen.", completion = "<Rexxar grinst.>\n\nDie Geschichte Eurer Heldentaten wird man sich noch jahrelang erzählen, {name}. Das Drachenfeueramulett ist der Schlüssel zu Onyxias Hort. Sammelt Eure Streitmacht und erobert ihn im Namen der Horde!" }, enUS = { progress = "Drakkisath is not to be trifled with, {name}. He is responsible for the death of thousands.", completion = "<Rexxar grins.>\n\nThe story of your heroics will be told for years to come, {name}. The Drakefire Amulet is the key to the lair of Onyxia. Gather your forces and conquer in the name of the Horde!" } })
apply(6603, { "classic", "forever" }, { deDE = { completion = "Hallo, Ihr da! Meggi hat Euch also schon von den Problemen erzählt, auf die ich hier gestoßen bin?" }, enUS = { completion = "Well, hi there! So Meggi told you of the trouble I have found here?" } })
apply(6604, { "classic", "forever" }, { deDE = { completion = "Aye, was kann ich für Euch tun?" }, enUS = { completion = "Aye, what can I do for you?" } })
apply(6605, { "classic", "forever" }, { deDE = { completion = "Ah, {class}. Also gibt es wohl doch noch Hoffnung. Seid Ihr hier, um mir zu helfen?" }, enUS = { completion = "Ah, {class}. I see that there is hope yet. Are you here to assist me?" } })
apply(6607, { "classic", "forever" }, { deDE = { progress = "Na, hat heute schon einer angebissen?", completion = "Also das nenn ich einen tollen Fang!\n\nKommt hier rüber, dann zeig ich Euch, wie man die Leinen auswirft." }, enUS = { progress = "Anything bitin' today?", completion = "Now that's a fine catch!\n\nCome over here, lemme show you how to set a few lines." } })
apply(6608, { "classic", "forever" }, { deDE = { completion = "Klar, Ihr müsst ein Freund von Lumak sein.\n\nAngeln? Ich kann Euch alles übers Angeln erzählen." }, enUS = { completion = "'Course, you must be a friend of Lumak's.\n\nFishin'? I can tell you all 'bout fishin'." } })
apply(6610, { "classic", "forever" }, { deDE = { progress = "Meine Gelüste bringen mich noch mal um! Schnell, {name}, bevor ich den Kitt aus den Fenstern futtere.", completion = "Freut Euch auf ein ganz besonderes Vergnügen, {name}. Seht zu und lernt!" }, enUS = { progress = "My cravings are going to be the end of me! Hurry, {name} - before I dip into my own supply.", completion = "You are in for a special treat, {name}. Watch and learn!" } })
apply(6611, { "classic", "forever" }, { deDE = { completion = "<Dirge spuckt ein paar Fetzen der Ledersandale aus.>\n\nPfui...\n\n<Dirge hustet laut.>\n\nWas? Ihr müsst wissen, dass Leder erstaunlich reich an Proteinen und arm an Kohlehydraten ist." }, enUS = { completion = "<Dirge spits out some leather sandal bits.>\n\nPfftooey...\n\n<Dirge hacks loudly.>\n\nWhat? I'll have you know that leather is surprisingly high in protein and low in carbohydrates." } })
apply(6621, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Häuptling Murgut besiegt, {name}? Habt Ihr das Fäulnisklauentotem?", completion = "Gute Arbeit, {name}. Indem wir die Fäulnisklauen herausgefordert und ihren Anführer besiegt haben, haben wir ihnen eine nachdrückliche Warnung erteilt:\n\nMan darf die Horde nicht unterschätzen.\n\nIch glaube, dass uns dieser Stamm für lange Zeit keine Scherereien mehr machen wird." }, enUS = { progress = "Did you defeat Chief Murgut, {name}?  Did you retrieve his Foulweald Totem?", completion = "Good work, {name}.  Issuing that challenge to the Foulwealds and defeating their leader sends them a strong message:\n\nThe Horde is not to be trifled with.\n\nI don't believe that tribe will be giving us much trouble for a long time." } })
apply(6622, { "classic", "forever" }, { deDE = { completion = "Doktor {name}, willkommen bei den Traumachirurgen der Horde." }, enUS = { completion = "Doctor {name}, welcome to Horde Trauma." } })
apply(6623, { "classic", "forever" }, { deDE = { completion = "Großartig. Zieht Eure Operationskluft an, dann werden wir sogleich beginnen!" }, enUS = { completion = "Wonderful. Put on your scrubs, we are to start at once!" } })
apply(6624, { "classic", "forever" }, { deDE = { completion = "Doktor {name}, willkommen bei den Traumachirurgen der Allianz." }, enUS = { completion = "Doctor {name}, welcome to Alliance Trauma." } })
apply(6625, { "classic", "forever" }, { deDE = { completion = "Großartig. Zieht Eure Operationskluft an, dann werden wir sogleich beginnen!" }, enUS = { completion = "Wonderful. Put on your scrubs, we are to start at once!" } })
apply(6626, { "classic", "forever" }, { deDE = { progress = "Wie läuft die Jagd, {name}? Wenn ich nur dieses kleine Beispiel der Macht dieses Diplomaten hier sehe, zweifle ich nicht mehr daran, dass die Geißel eine der größten Bedrohungen ist, die die Welt je gesehen hat.", completion = "Danke, {name}! Die Arbeit, die Ihr geleistet habt, wird eine große Hilfe sein, da bin ich mir sicher.\n\nIch werde meine Studien über diesen Diplomaten und den Rest der Stacheleber hier fortsetzen. Wenn Ihr auf größere Abenteuer aus seid, würde ich ein paar Freunde zusammentrommeln und in die Höhle da drüben gehen, die wie ein riesiges Ebermaul aussieht. Ich bin sicher, dass Ihr dort drinnen noch auf viel größere Herausforderungen stoßen werdet." }, enUS = { progress = "How goes the hunt, {name}? Seeing just this small sample of this diplomat's power here removes any doubt I had that the Scourge are one of the greatest threats this world has ever seen.", completion = "Thank you, {name}! The work you've done will be a great help, I'm sure.\n\nI will continue my study of this diplomat and the rest of the quilboar here. If you seek greater adventure, I'd find a few friends and head into the cave that looks like a great boar maw just over there. I'm sure once you're inside you'll find greater challenges to face." } })
apply(6627, { "classic", "forever" }, { deDE = { progress = "Das Leben ist voller Fragen, {class}. Ihr werdet sie niemals alle beantworten können, aber mit der Zeit und durch Studien werdet Ihr Euch bestimmt weiteres Wissen aneignen.", completion = "Gut gemacht, {class}. Ihr habt den Text studiert, wie ich Euch gebeten habe, und jetzt habt Ihr eine weitere unserer Prüfungen bestanden." }, enUS = { progress = "Life is full of questions, {class}. You will never be able to answer all of them, but with some time and study, perhaps you will become a little more knowledgeable.", completion = "Well done, {class}. You have studied the text I asked you to, and now you have passed another of our tests." } })
apply(6628, { "classic", "forever" }, { deDE = { completion = "Gut gemacht, {name}. Ich hatte meine Zweifel, ob Ihr den Text studieren würdet, den ich Euch gebeten habe zu holen, aber Ihr habt richtig geantwortet." }, enUS = { completion = "Well done, {name}. I had my doubts if you studied the text I asked you to get, but you've answered correctly." } })
apply(6629, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Grundig Finsterwolke und seine persönliche Schlägerbande getötet?", completion = "Grundig Finsterwolke ist tot! {name}, ich werde immer für das dankbar sein, was Ihr heute hier geleistet habt." }, enUS = { progress = "Have you killed Grundig Darkcloud and his personal band of Brutes?", completion = "Grundig Darkcloud is dead! {name}, I will always be grateful for what you've done here today." } })
apply(6641, { "classic", "forever" }, { deDE = { completion = "Ich habe schon viele Nagaangriffe miterlebt, seit ich hier bin. Es beruhigt mich, dass Vorsha nicht mehr ihr Unwesen treibt.\n\nWir stehen in Eurer Schuld, {name}." }, enUS = { completion = "I have witnessed many naga attacks since I arrived here. It puts my mind at ease that Vorsha will no longer roam freely.\n\nWe are in your debt, {name}." } })
apply(6661, { "classic", "forever" }, { deDE = { progress = "Harrr... Deckschrubber, was dauert das so lange?", completion = "Die sind ausgezeichnet, Kumpel. Mein Bruder braucht sie quietschlebendig und zappelig, sonst verderben sie... Ihr wollt doch wohl keinen verdorbenen Rattenkebab probieren, was?" }, enUS = { progress = "Yarrr... Swabby, what be takin' ye so long?", completion = "These'll werk nicely, matey. Me brother needs em still tickin' and kickin,' else they go sour... Ye don't want to taste no sour rat kabob." } })
apply(6662, { "classic", "forever" }, { deDE = { progress = "<Nipsy steckt seinen Zeigefinger in eines der Luftlöcher des Kartons.>\n\nQuietschlebendig und zappelig... und genau zur richtigen Zeit!", completion = "Armer Monty. Seit dem Gnomeregan-Vorfall ist er ein anderer Mensch. Der Junge hat in seinem ganzen Leben noch kein Meer gesehen, ganz zu schweigen von irgendwelchen Piraten.\n\n<Nipsy seufzt.>\n\nZumindest sorgt er dafür, dass es immer Nachschub an quirligen Viechern gibt." }, enUS = { progress = "<Nipsy puts his index finger through one of the air holes in the carton.>\n\nAlive and kicking... and just in time!", completion = "Poor Monty. Ever since the Gnomeregan incident, he hasn't been the same. That boy has never seen an ocean in his life, let alone being some kind of pirate.\n\n<Nipsy sighs.>\n\nAt least he keeps the flow of twitching critters coming." } })
apply(6681, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Milton getroffen?\n\n<Fahrad lacht.>", completion = "Äußerst exzellent, junger Dieb.\n\nIhr seht etwas mitgenommen aus, aber das wird schon wieder.\n\nEine lange Reise erwartet Euch - lang und profitabel. Seid Ihr bereit, Euer Schicksal unter den Meistern von Ravenholdt zu schmieden?\n\nSprecht mit den Wachen da draußen. Sie werden Euch einweisen." }, enUS = { progress = "Did you meet Milton?\n\n<Fahrad laughs.>", completion = "Most excellent, young thief.\n\nYou look a bit beaten down, but no worse for the wear.\n\nA long journey awaits you - long and rewarding. Are you prepared to finally embrace your destiny among the masters of Ravenholdt?\n\nSpeak with the guards outside. They will get you started." } })
apply(6761, { "classic", "forever" }, { deDE = { completion = "Vielen Dank, dass Ihr gekommen seid, {class}. Ich entschuldige mich für das Missverständnis... es gibt viel Misstrauen zwischen dem Erzdruiden hier und dem Bewahrer Remulos in Moonglade. Jeder verdächtigt den anderen der Schikane und die Tatsache, dass die merkwürdige Verderbnis von Teldrassil auch weiterhin nicht nachlässt, ist hier immer noch ein Thema. Das trägt wenig dazu bei, das Misstrauen zu lindern.\n\nTrotzdem bleibt unsere Pflicht gegenüber dem Zirkel des Cenarius bestehen... auch wenn diejenigen, die ihn leiten, untereinander uneins sind." }, enUS = { completion = "Yes {class}, thank you for coming.  I apologize about the misunderstanding... the air is thick with mistrust between the Arch Druid here and Keeper Remulos in Moonglade.  Each suspect the other of chicanery, and the fact that strange corruptions of Teldrassil continue unabated are still an issue here.  It does little to quell mistrust.\n\nRegardless, our duty to the Cenarion Circle remains... even if those who lead it may disagree with one another." } })
apply(6762, { "classic", "forever" }, { deDE = { completion = "Ich bin Rabine Saturna und heiße Euch im Namen von Bewahrer Remulos und allen Bewohnern dieses hochheiligen Tales aufs Herzlichste willkommen.\n\nIch weiß Euer Interesse und Euren Eifer bei der Unterstützung des Zirkels des Cenarius zu schätzen. Ich weiß außerdem, dass der Erzdruide von Darnassus sein Missfallen darüber ausgedrückt hat, dass Ihr uns unterstützt. Seid versichert, dass es zum Guten ist und dass Ihr gegen alle schlechten Auswirkungen gefeit seid, deren Ziel Ihr sein mögt.\n\nIhr seid hier unter Freunden, {name}." }, enUS = { completion = "I am Rabine Saturna, and on behalf of Keeper Remulos and all of the denizens of this sacred glade I bid you welcome.\n\nI appreciate your interest and eagerness to assist the Cenarion Circle.  I also know that Arch Druid of Darnassus expressed his displeasure to you in your lending us aid.  Rest assured that it is for the greater good, and that you will be safe from any ill-conceived repercussions you may be the target of.\n\nYou are among friends here, {name}." } })
apply(6804, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Armschienen?", completion = "Ihr habt Eure Sache gut gemacht, {class}. Die verderbten Elementare, die Ihr geheilt habt, waren ein Frevel für alle Gewässer. Unsere Kraft liegt in unserer Reinheit und wenn wir unseren Krieg mit den anderen gewinnen wollen, müssen wir stark bleiben." }, enUS = { progress = "Do you have the bracers?", completion = "You have done well, {class}.  The corrupted elementals you cured were an outrage to all bodies of water.  Our strength lies in our purity and if we are to win our war with the others, we must remain strong." } })
apply(6805, { "classic", "forever" }, { deDE = { progress = "Feigheit ist keine Sache, die wir begrüßen, {class}. Begebt Euch nach Silithus und beweist Euren Mut.", completion = "Euer Mut ist bewiesen, ebenso wie Euer Wert für uns. Vielleicht habe ich in der Zukunft Aufgaben für Euch, die sich eher eines geschätzten Verbündeten der Wasserlords ziemen." }, enUS = { progress = "Cowardice is not a thing we hold in regard, {class}.  Go to Silithus and prove your bravery.", completion = "Your bravery is proven, as is your worth to us.  Perhaps I may have future tasks for you, tasks more befitting a valued ally of the Waterlords." } })
apply(6821, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Auge, {class}? Seid Ihr stark genug, die Blackrockspitze zu betreten?", completion = "Ah, Ihr habt also die Kraft. Und Ihr habt auch die benötigte Schlauheit, denn die Blackrockspitze erfordert mehr als rohe Gewalt.\n\nIn der Tat, {name}, Ihr könntet Euch für uns noch als geschätzter Verbündeter erweisen..." }, enUS = { progress = "Do you have the Eye, {class}?  Do you have the strength to enter Blackrock Spire?", completion = "Ah, so you do have the strength.  And you have the cunning as well, for Blackrock Spire is more than a match for brute strength alone.\n\nIndeed {name}, you may yet prove a valued ally to us..." } })
apply(6822, { "classic", "forever" }, { deDE = { completion = "Ihr habt getan, was die meisten Eurer Art für unmöglich halten würden. Ihr seid den Wesen des geschmolzenen Kerns gegenübergetreten und habt triumphiert!\n\nFür eine so kleine Kreatur habt Ihr großes Potenzial gezeigt.\n\nEines Tages erreichen wir möglicherweise ein echtes Bündnis zwischen Eurer Art und den Wasserlords." }, enUS = { completion = "You have done what most of your kind would think impossible.  You have faced the beings of the Molten Core, and triumphed!\n\nFor so small a creature, you have displayed great resource.\n\nSome day, perhaps we might strike a true allegiance between your kind and the Waterlords." } })
apply(6823, { "classic", "forever" }, { deDE = { completion = "Die Kunde Eurer Heldentaten gegen unsere Feinde hallt in der Kammer der Wasserlords wider, {name}. Einige waren der Meinung, dass Eure Gestalt zu klein und zerbrechlich sei, um in unserem Krieg zu kämpfen, aber Ihr habt viel gewonnen. Ihr habt Euch unter uns Respekt verdient, ein unglaubliches Kunststück." }, enUS = { completion = "Your exploits against our enemies ring through the chambers of the Waterlords, {name}.  It was thought by some that your form is too small and fragile to fight in our war, but you have made great gains.  You have earned respect among us, an unbelievable feat." } })
apply(6824, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Lucifron und die anderen besiegt, {name}? Habt Ihr die Hände des Feindes?", completion = "Ihr habt die Hände! Die besiegten Feuer-Captains! Ich hätte es nicht für möglich gehalten, wenn ich Euch nicht kennen würde und wüsste, wozu Ihr fähig seid.\n\n{name}, Eure Heldentaten sind ohne Zahl, aber die Kunde von dieser letzten Heldentat wird unter den Wasserlords Wellen schlagen. Euer Name könnte eines Tages eine Legende unter uns sein.\n\nSprecht wieder mit mir, {name}. Ich habe möglicherweise noch eine weitere Aufgabe ..." }, enUS = { progress = "Have you defeated Lucifron and the others, {name}?  Do you have the hands of the enemy?", completion = "You have the hands!  You defeated the fire captains!  I would not have thought it possible, had I not known you and what you are capable of.\n\n{name}, your exploits are without number, but word of this last feat will send waves among the Waterlords.  Your name may one day be legend to us.\n\nSpeak with me again, {name}.  I may have yet another task..." } })
apply(6844, { "classic", "forever" }, { deDE = { progress = "Oh, hallo! Hrmm...\n\nLasst mich ehrlich zu Euch sein... Ihr riecht ein wenig streng. Abgestanden, könnte man sagen. Aber ich möchte Eure Person nicht angreifen. Ich sage nur... in Zukunft solltet Ihr Euch ein wenig frisch machen, wenn Ihr vom Schlachtfeld kommt. Damit könnte der erste Eindruck wesentlich positiver ausfallen!\n\nAber egal... was kann ich für Euch tun?", completion = "Heiliger Bimbam! Was habt Ihr denn da? Ich würde sagen, es hat die Form eines Buches... Ich werde versuchen, die Schale darum aufzubrechen.\n\nLayo hat Euch aus Silithus zu mir geschickt? Ich habe nur ein paar geflüsterte Gerüchte gehört - die ja wohl nicht unbedingt geflüstert sind, wenn man's genau nimmt - über die Schrecken, die dort draußen vor sich gehen. Verbindet das mit meiner Abneigung gegen alles Käferähnliche und Ihr habt ein Rezept, damit ich hier bei diesen Büchern bleibe!" }, enUS = { progress = "Why, hello there!  Hrmm...\n\nLet me be a little honest with you, friend... you smell a bit ripe.  Whiffy, one might say.  Now I'm not making a personal assailment of your being.  I'm just saying... in the future, you may want to freshen up a little after coming in from the field.  It will make those first impressions a little more positively impressionable!\n\nAnyhoo... what can I do for you?", completion = "Well great monkey toads!  What have you got here?  It's sort of book shaped, I guess... I'll try and crack this shell on it.\n\nLayo sent you to me from Silithus?  I've only heard very hushed rumblings - which I guess aren't all that hushed when you think about it - about the horrors that are going on out there.  Couple that with my lack of pleasure for anything bug-like, and you've got the recipe for me needing to stay here with the books!" } })
apply(6845, { "classic", "forever" }, { deDE = { completion = "Ah, {name}... ich hatte gehofft, dass Ihr vorbeikommen würdet. Es ist schön, Euch gesund und munter zu sehen.\n\nIch hatte Nachricht erhalten, dass Ihr vom Schlachtfeld herkommen würdet, und ich wollte persönlich die Dankbarkeit des Zirkels des Cenarius für die Unterstützung zum Ausdruck bringen, die Ihr uns bisher angedeihen ließet. Zweifellos gibt es noch weitere Geheimnisse über die Silithus zu enthüllen. Eure Lieferung an Umber sollte sich als sehr interessant erweisen, wenn sie erst enthüllt ist. Nehmt dies bitte als Zeichen unserer kontinuierlichen Wertschätzung für Eure Hilfe.\n\nDanke, {class}." }, enUS = { completion = "Ah, {name} - I had hoped you would stop by.  I am glad to see you well.\n\nI received notice you would be coming in from the field, and I wanted to personally express the Cenarion Circle's gratitude for the assistance you've given us thus far.  No doubt there are more secrets to uncover from Silithus; your delivery to Umber should prove most interesting once uncovered.  Please, accept this as a token of our continued appreciation for your aid.\n\nThank you, generous {class}." } })
apply(6921, { "classic", "forever" }, { deDE = { progress = "Konntet Ihr den Fathom-Kern finden? Ohne ihn haben wir keine Ahnung, was genau die Twilight-Hammer da unten vorhaben.", completion = "Genau das brauche ich! Ein Fathom-Kern ist ein unglaublicher Quell an Informationen, aus denen wir guten Nutzen ziehen können. Was auch immer die Twilight-Hammer da unten im Schilde führen - und glaubt mir, wenn ich sage, dass es nichts Gutes sein kann -, meine Kollegen und ich werden es jetzt aufdecken.\n\nIhr habt Eure Sache hier heute gut gemacht. Der Irdene Ring ist Euch sehr dankbar für Eure Hilfe. Ihr habt außerdem der Horde als Ganzes geholfen, und darauf solltet Ihr stolz sein." }, enUS = { progress = "Have you been successful in locating the fathom core?  Without it we'll have no idea what the Twilight's Hammer is exactly up to down there.", completion = "This is exactly what I need!  A fathom core is an incredible well of information that we will be able to draw much good from.  Whatever the Twilight's Hammer is up to in there - and believe me when I say it is no good - my comrades and I will now uncover.\n\nYou've done well here today; the Earthen Ring looks upon you warmly for assisting us.  You've also helped the Horde as a whole, and for that you should be proud." } })
apply(6922, { "classic", "forever" }, { deDE = { progress = "Ach, hallo, {name}. Ich habe gerade in den Wellen der See gelesen, wie ich es immer tue. Was führt Euch in den Außenposten?", completion = "Das... das ist ein wichtiger Fund, {name}.\n\nIhr habt dies von Baron Aquanis aus Blackfathom, sagt Ihr? Man hatte Baron Aquanis schon lange im Verdacht, eine verderbte Elementarkraft zu sein. Diese Kugel wird zeigen, was genau ihn verdorben hat. Es würde mich nicht im Geringsten überraschen, wenn es sich dabei um die Twilight-Hammer handelt. Aber unsere Studien werden auch aufzeigen, wie sie das getan haben.\n\nIhr habt das Richtige getan, indem Ihr dies zu mir brachtet. Bitte, nehmt dies zusammen mit den wärmsten Empfehlungen des Irdenen Rings." }, enUS = { progress = "Ah, hello again {name}.  I was just reading the waves the sea, much like I always do.  What brings you to the outpost?", completion = "This... this is quite the find, {name}.\n\nYou acquired this from Baron Aquanis in Blackfathom, you say?  Baron Aquanis has long been thought of as a corrupted elemental power; this globe will prove what exactly had corrupted him.  While it would be no surprise if it turned out to be the Twilight's Hammer, our studies will also show how they did it as well.\n\nYou did well in bringing this to me.  Please - take this, along with the Earthen Ring's warmest regards." } })
apply(6961, { "classic", "forever" }, { deDE = { completion = "Ho, ho, hallo! Ich bin Altvater Winter und ich - mit den besten Wünschen von Kokelwälder... ''Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost' - möchte Euch ein phantastisches Winterhauchfest wünschen.\n\n Wenn Ihr in diesem Jahr brav wart, dann erhaltet Ihr vielleicht Leckereien von Kokelwälder als Gaumenfreuden zum Winterhauchfest. Hussah!" }, enUS = { completion = "Ho ho hello.  I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... \"Fresh from our farm to your plate, it's Smokywood Pastures wholesome goodness\" - would like to wish you a fantastic Feast of Winter Veil.\n\nIf you've been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah." } })
apply(6963, { "classic", "forever" }, { deDE = { completion = "I-I-Ihr könnt mich h-h-hören! G-G-Gott sei Dank!\n\nIch bin nicht wirklich ein S-S-Schneemann - mein N-N-Name ist Sacks und ich a-a-arbeite für die N-N-Niederlassung von Kokelwälder in Orgrimmar. Ich w-w-wurde hierher geschickt, um n-n-nach einem vermissten Paket zu suchen, als ich von einer K-K-Kreatur angegriffen wurde, die ich n-n-noch nie gesehen habe!\n\nSo k-k-kalt ..." }, enUS = { completion = "Y-y-you can h-h-hear me!  Thank the b-b-bottom line!\n\nI'm not really a s-s-snowman - my n-n-name is Sacks, and I w-w-work for the Orgrimmar b-b-branch of Smokywood Pastures... I g-g-got sent out here to look for a m-m-missing package, when I was attacked by a c-c-creature I have never seen b-b-before!\n\nSo v-v-very cold..." } })
apply(6964, { "classic", "forever" }, { deDE = { completion = "Das Winterhauchfest, sagt Ihr? Ach ja, in vergangenen Zeiten hatte es für uns Tauren eine wirkliche Bedeutung. Heutzutage hingegen haben andere die Legende dieser Feiertage der Erneuerung zur verkaufsfördernden Maßnahme für Bonbons und Geschenke gemacht.\n\nEs ist nicht verwunderlich, dass Furmund diese Veränderung bitter aufstößt. Er und andere Tauren wie er hängen an unserer Vergangenheit wie an einem Kriegsbanner. Ich denke zwar, dass ein bisschen Feiern immer gut ist, aber es ist auch wichtig, sich an die Ursprünge des Festes zu erinnern." }, enUS = { completion = "The Feast of Winter Veil, you say?  Alas, in times past it held a more substantial meaning to us tauren.  Nowadays, it seems as though others have turned the legend of this season of renewal into something that helps to sell candies and presents.\n\nIt's no surprise that Furmund is bitter about that sort of change.  He and other tauren like him cling to our past like a banner of war.  While I think a little celebration is always good, it is important to remember the origins of the Feast." } })
apply(6981, { "classic", "forever" }, { deDE = { progress = "Hallo, {race}. Was kann ich für Euch tun?", completion = "Oh... So etwas habe ich noch nie gesehen..." }, enUS = { progress = "Hello, {race}. What can I do for you?", completion = "Oh... I have never seen anything like this..." } })
apply(6984, { "classic", "forever" }, { deDE = { completion = "Ho, ho, hallo!\n\nDie Goblins haben mir gesagt, dass Ihr in dieser Feiertagszeit ein besonderes Geschenk verdient habt, und ich freue mich, es Euch überreichen zu dürfen. Bitte schön - ich wünsche Euch für dieses Jahr und für alle kommenden Jahre ein wunderbares Winterhauchfest." }, enUS = { completion = "Ho ho hello, adventurer!\n\nThe goblins told me that you have earned a special gift this holiday season, and I am pleased to give it to you.  Here you go - have a wondrous Feast of Winter Veil this and every season in the future." } })
apply(7001, { "classic", "forever" }, { deDE = { progress = "Ohne Eure Hilfe, hätten die Frostwolfreiter keine Reittiere um in die Schlacht zu ziehen. Ihr erweist uns einen großen Dienst!", completion = "Ich kann nur hoffen das andere die mit dem Sammeln von Widderbälgern beauftragt wurden, ebenso motiviert sind wie Ihr, {name}.\n\nBei diesem Arbeitstempo, werden die Ställe in wenigen Stunden wieder voll sein!" }, enUS = { progress = "Without your help, the Frostwolf Wolf Riders would not have mounts to ride into battle. You do us a great service!", completion = "I can only hope that those charged with collecting ram hides are as determined as you, {name}.\n\nAt this rate, we will have the stables full in a matter of hours!" } })
apply(7003, { "classic", "forever" }, { deDE = { progress = "Schrumpf-Überreste, versichere Ich Euch, sind eine wertvolle Handelsware, was das Ingenieurswesen angeht! Nunja, es ist insofern schon wertvoll, als dass es mir hilft den Schrumpfer zu kontrollieren, sodass er nicht beim Benutzen explodiert.\n\nOh, natürlich meine ich andere Schrumpfer als den, den ich Euch gab. Natürlich ist es ein anderer!", completion = "Großartig! Wie ich sehe, habt Ihr nicht nur die Überreste mitgebracht, sondern seid sogar noch in einem Stück! Äh,... natürlich gab es nie irgendwelche Gefahren bei der Verwendung des Ultra-Schrumpfers.\n\nIch muss mich bei Euch für Eure Bemühungen bedanken, {name}. Ihr seid ein wirklicher Freund der Goblins. Akzeptiert dies als Zeichen meiner Dankbarkeit!" }, enUS = { progress = "Miniaturization residue, I assure you, is a valuable commodity when it comes to engineering!  Well, it is valuable in that it helps me make sure the zapper won't do something as disappointing as explode on the user.\n\nOh, I mean for the zappers other than the one I gave you.  Absolutely!", completion = "Splendifimous!  Not only am I glad to see that you've returned with the residue, but also with all your major appendages intact!  That is, well, there was never any danger in using the Ultra-Shrinker, now was there!\n\nI do appreciate your effort on my behalf, {name}.  Truly, you are a friend to goblins everywhere.  Accept this as a token of my appreciation!" } })
apply(7021, { "classic", "forever" }, { deDE = { completion = "Ho, ho, hallo! Ich bin Altvater Winter und ich - mit den besten Wünschen von Kokelwälder... 'Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost' - möchte Euch ein phantastisches Winterhauchfest wünschen.\n\nWenn Ihr in diesem Jahr brav wart, dann erhaltet Ihr vielleicht Leckereien von Kokelwälder als Gaumenfreuden zum Winterhauchfest. Hussah!" }, enUS = { completion = "Ho ho hello.  I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... \"Fresh from our farm to your plate, it's Smokywood Pastures wholesome goodness\" - would like to wish you a fantastic Feast of Winter Veil.\n\nIf you've been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah." } })
apply(7024, { "classic", "forever" }, { deDE = { completion = "Ho, ho, hallo! Ich bin Altvater Winter und ich - mit den besten Wünschen von Kokelwälder... 'Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost' - möchte Euch ein phantastisches Winterhauchfest wünschen.\n\nWenn Ihr in diesem Jahr brav wart, dann erhaltet Ihr vielleicht Leckereien von Kokelwälder als Gaumenfreuden zum Winterhauchfest. Hussah!" }, enUS = { completion = "Ho ho hello.  I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... \"Fresh from our farm to your plate, it's Smokywood Pastures wholesome goodness\" - would like to wish you a fantastic Feast of Winter Veil.\n\nIf you've been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah." } })
apply(7028, { "classic", "forever" }, { deDE = { progress = "Stellt keine Fragen!\n\nIhr wisst, was ich will.", completion = "Ha ha ha! Ich wusste, Ihr würdet zurückkehren.\n\n<Willow murmelt vor sich hin.>\n\n... So leicht zu überzeugen.\n\n... Würde alles tun, solange der Preis stimmt. Hi, hi, hi…" }, enUS = { progress = "Don't ask questions!\n\nYou have my request.", completion = "Ha ha ha! I knew you'd be back.\n\n<Willow mutters.>\n\n...So easy to convince.\n\n...Will do anything for the right price. Heh heh heh..." } })
apply(7029, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr die Pflanze heilen könnt, wird sie erneut zu wachsen beginnen. Wir müssen tun, was wir können, {name}...", completion = "Danke, dass Ihr das zurückgebracht habt, {name}. Mit der verbleibenden Flüssigkeit, die Ihr mir gebracht habt, kann ich meine Studien fortsetzen.\n\nEs gibt zwar immer noch viel zu tun, aber Ihr habt geholfen, einen Teil der Verderbnis zu heilen, die Schlangenzunge über Maraudon gebracht hat. Nehmt dies bitte zusammen mit meiner Dankbarkeit an." }, enUS = { progress = "If you are able to heal the plant, it will again begin to grow. We must do what we can, {name}...", completion = "Thank you for returning this, {name}. With the remaining liquid you brought me, I can continue my studies.\n\nWhile there is still much to do, you have helped to heal some of the corruption that Vyletongue spread through Maraudon. Please take this with my gratitude." } })
apply(7041, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr die Pflanze heilen könnt, wird sie erneut zu wachsen beginnen. Wir müssen tun, was wir können, {name}...", completion = "Danke, dass Ihr das zurückgebracht habt, {name}. Mit der verbleibenden Flüssigkeit, die Ihr mir gebracht habt, kann ich meine Studien fortsetzen.\n\nEs gibt zwar immer noch viel zu tun, aber Ihr habt geholfen, einen Teil der Verderbnis zu heilen, die Schlangenzunge über Maraudon gebracht hat. Nehmt dies bitte zusammen mit meiner Dankbarkeit an." }, enUS = { progress = "If you are able to heal the plant, it will again begin to grow. We must do what we can, {name}...", completion = "Thank you for returning this, {name}. With the remaining liquid you brought me, I can continue my studies.\n\nWhile there is still much to do, you have helped to heal some of the corruption that Vyletongue spread through Maraudon. Please take this with my gratitude." } })
apply(7044, { "classic", "forever" }, { deDE = { progress = "Ich bin aus einem Alptraum erwacht, der niemals enden wollte...", completion = "Da Ihr nun die beiden Teile meines Szepters zurückgeholt habt, hoffe ich, dass Maraudon eines Tages von der Vyle-Verderbnis befreit ist." }, enUS = { progress = "I have awoken from a nightmare that seemed it would never end...", completion = "Now that you have recovered the two parts of my scepter, I have hope that Maraudon may one day be rid of the Vyle corruption." } })
apply(7046, { "classic", "forever" }, { deDE = { completion = "Bitte nehmt dies und wisset, dass die Macht, die Euch zugeteilt wurde, nur genutzt werden darf, um Gutes zu tun. Setzt Eure Reise durch diese Höhlen fort, und vielleicht werdet Ihr die Überreste meines Onkels finden. Große Gefahren liegen vor Euch, {name}.\n\nSprecht erneut mit mir, falls es nötig ist." }, enUS = { completion = "Please take this, and know that the power allotted to you now must be used for good. Continue your journey through the caverns, and with hope, you will find the remains of my uncle. Much danger awaits you, {name}.\n\nSpeak with me again should the need arise." } })
apply(7062, { "classic", "forever" }, { deDE = { completion = "Das Winterhauchfest, sagt Ihr? Ach ja, in vergangenen Zeiten hatte es für uns Zwerge eine wirkliche Bedeutung. Heutzutage hingegen haben andere die Legende von Altvater Winter zu einer verkaufsfördernden Maßnahme für Bonbons und Geschenke gemacht.\n\nEs ist nicht verwunderlich, dass Goli diese Veränderung bitter aufstößt. Er und andere Zwerge wie er hängen an unserer Vergangenheit wie an einem Kriegsbanner. Ich denke zwar, dass ein bisschen Feiern immer gut ist, aber es ist auch wichtig, sich an die Ursprünge des Festes zu erinnern." }, enUS = { completion = "The Feast of Winter Veil, you say?  Alas, in times past it held a more substantial meaning to us dwarves.  Nowadays, it seems as though others have turned the legend of Greatfather Winter into something that helps to sell candies and presents.\n\nIt's no surprise that Goli is bitter about that sort of change.  He and other dwarves like him cling to our past like a banner of war.  While I think a little celebration is always good, it is important to remember the origins of the Feast." } })
apply(7064, { "classic", "forever" }, { deDE = { completion = "Das sind wirklich ganz wunderbare Nachrichten, {name}! Danke!\n\nIch werde mit Marandis sprechen und um sein Wissen zum Thema Zaetars Überreste bitten, aber zumindest habt Ihr die schwierigste der Aufgaben bereits bewältigt.\n\nMir wurde gesagt, dass ich diejenigen belohnen darf, die uns geholfen haben, wenn wir bei unserer Mission erfolgreich sein sollten. Als Geschenk unseres Volkes habe ich diese Gegenstände erhalten - wählt einen davon." }, enUS = { completion = "This is most wonderful news, {name}! Thank you!\n\nI will speak with Marandis and ask his wisdom on the topic of Zaetar's remains, but at least you have overcome the hardest of the tasks.\n\nI was told that if we were successful in our mission, I had permission to reward those who aided us. I was given these items as tokens from our people--you may choose one." } })
apply(7065, { "classic", "forever" }, { deDE = { completion = "Das sind wirklich ganz wunderbare Nachrichten, {name}! Danke!\n\nEs beunruhigt mich zwar, dass Ihr die Überreste von Zaetar nicht zurückbringen konntet, aber wer bin ich, dass ich den Willen des Erstgeborenen von Cenarius in Frage stelle? Vielleicht wird der Wille der Zentauren nun brechen und ihr Blutdurst versiegen - wir können es nur hoffen.\n\nFür den Fall, dass unsere Mission von Erfolg gekrönt sein sollte, habe ich diese Gegenstände erhalten, um jene zu belohnen, die uns halfen. Ihr dürft einen dieser Gegenstände als Zeichen der Dankbarkeit wählen." }, enUS = { completion = "This is most wonderful news, {name}! Thank you!\n\nAlthough it concerns me that you were not able to bring back Zaetar's remains, who am I to question the will of Cenarius' first born. Perhaps now the will of the centaur will break and their thirst for blood will lesson--we can only hope.\n\nIf successful in our mission, I was given these items to reward any who aided us. You may choose one as a token of thanks." } })
apply(7066, { "classic", "forever" }, { deDE = { progress = "Euch haftet der Geruch der Verderbnis an, {name}... wie so vielen Abenteurern in diesen Tagen. Aber etwas an Euch ist anders. Gibt es etwas, über das Ihr mit mir sprechen wollt? Ihr seid von einer Aura umgeben, die vertraut scheint, aber ich kann sie nicht einordnen.\n\nBitte, ich flehe Euch an, sagt mir, warum Ihr mich sehen wolltet.", completion = "Mein Bruder hat also endlich seinen Frieden gefunden? Ich bin stolz, dass ich diesen Tag erleben darf. In seiner ganzen Arroganz und seiner Wut dachte ich wahrlich, er wäre für uns verloren, aber dieses... dieses Symbol seines Opfers beweist eindeutig, dass er nicht verloren ist - er wurde nur neu geboren. Er nimmt seinen Platz in der Natur ein, wie es seine Pflicht war.\n\nIch danke Euch, {name}. Indem Ihr mir dies brachtet, habt Ihr mir ein wenig Hoffnung geschenkt, die ich schon für vergeblich hielt. Dieses Samenkorn wird für die Menschen in diesem vom Krieg zerrissenen Land eines Tages wichtig sein... Das kann ich spüren." }, enUS = { progress = "You have the scent of corruption on you, {name}... much like many adventurers these days. But something about you is different. Is there something you've come to speak to me about? You have an aura about you that seems familiar, but I cannot place it.\n\nPlease, I implore you, tell me why you've sought an audience with me.", completion = "So my brother has finally found peace? I am proud to have lived to see this day. In all his arrogance and anger, I truly thought he was lost to us, but this... this symbol of his sacrifice only proves that he is not lost--he has only been reborn. He takes his place in nature as was his duty.\n\nThank you, {name}. By bringing this to me, you have secured a small amount of hope that I thought I had once lost. This seed will be important to the people of this war-torn land some day... I can sense it." } })
apply(7067, { "classic", "forever" }, { deDE = { progress = "Wie habt Ihr Euch entschieden, {name}? Könntet Ihr mir helfen? Werdet Ihr Euren Fuß auf heiligen Boden setzen, um mir zu helfen, einen großen Zentaurenstamm zu schmieden!?", completion = "Das ist es, {race}! Das ist es! Jetzt kann ich die große Aufgabe der Vereinigung der Stämme angehen. Seid bedankt.\n\nNehmt bitte dies für Eure Bemühungen. Ich hoffe, dass über unserem nächsten Treffen ein glücklicherer Stern stehen wird." }, enUS = { progress = "What did you decide, {name}? Can you help me? Will you set foot on holy ground to help me forge one great centaur tribe!?", completion = "This is it, {race}! This is it! Now I can begin the great task of uniting the tribes. Thank you.\n\nTake this for your efforts, please. I hope when next we meet, it will be on much different terms." } })
apply(7068, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Kristalle schon gefunden? Rituale der Macht, Zauber von großer Kraft - diese Schattensplitter könnten bei allen Arten arkaner Magie hilfreich sein.", completion = "Ah, diese sind perfekt für meine Magie. Hier, nehmt eines dieser Schmuckstücke und macht Euch auf den Weg... ich habe hier viel zu tun." }, enUS = { progress = "You find the crystals yet? Rituals of power, spells of great strength--those shadowshards maybe very helpful in all kind of arcane magics.", completion = "Ah, these be perfect for me magics. Here, you take one of these trinkets and be on your way... me got much studyin' to do." } })
apply(7070, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Reise schon unternommen? Ich weiß, dass es recht gefährlich ist, aber wenn Ihr Erfolg habt, soll es Euer Schaden nicht sein.", completion = "Die sind perfekt, {name}. Es sind bereits andere Abenteurer von dort zurückgekehrt, und dadurch konnte ich dies herstellen... bitte, nehmt eines der Stücke für Eure harte Arbeit. Und ich danke Euch nochmals, dass Ihr mir weitere Proben für meine Studien besorgt habt." }, enUS = { progress = "Have you made the trip yet? I realize it'd be quite dangerous, but if you were successful, it would very much be worth it.", completion = "These are perfect, {name}. I actually had other adventurers return from there also and from them I was able to fashion these... please, feel free to take one for your hard work. And thank you again for more samples to study." } })
apply(7201, { "classic", "forever" }, { deDE = { progress = "<Sie reibt sich die Hände.>\n\nZeigt sie mir!", completion = "Großartig! Ich werde das sofort mit einem Kurier nach Undercity schicken lassen.\n\nUnd was Euch angeht: Hier ist die versprochene Bezahlung. Behaltet den Rest, dreckige Bestie!" }, enUS = { progress = "<Rubs her hands together.>\n\nShow them to me!", completion = "Wonderful! I will have these sent by courier to the Undercity at once!\n\nAs for you - here is payment, as promised. Keep the change, you filthy beast!" } })
apply(7221, { "classic", "forever" }, { deDE = { description = "Ah, {name}, Ihr wollt Euch zum Dienst melden, oder? Großartig, die Stormpikes können jeden, der sich freiwillig mustern lässt, gebrauchen!\n\nSprecht mit Ausgrabungsleiter Stonehewer in Dun Baldar. Momentan sucht sie nach Freiwilligen für eine entscheidende Mission im Feindesland. Ihr findet sie unterhalb der Dun Baldar Garnison.\n\nUnd haltet ein Auge offen während Ihr durch Dun Baldar geht. Für einen hart arbeitenden {class} gibt es viel zu tun, sofern Ihr nicht davor zurückscheut Euch die Hände schmutzig zu machen.", objectives = "Sprecht mit Ausgrabungsleiter Stonehewer in der Garnison von Dun Baldar." } })
apply(7222, { "classic", "forever" }, { deDE = { description = "Ah, ein {class}! Wir sind alle hoch erfreut Euch hier in Alterac anzutreffen, {name}. Zwergische Eindringlinge und ihre Verbündeten sind in unser Tal einmarschiert und wir sind froh über jedes Mitglied der Horde, das uns in dieser gerechten Schlacht zur Seite steht!\n\nSprecht mit Voggah Deathgrip. Er sucht nach Freiwilligen für eine wichtige Mission. Es geht um die Allianzfestung hier im Alteractal!\n\nIhr findet Voggah in Burg Frostwolf.", objectives = "Sprecht mit Voggah in Burg Frostwolf." } })
apply(7321, { "classic", "forever" }, { deDE = { progress = "Hattet Ihr Erfolg bei der Suche nach den Zutaten? Ich sag Euch, dieses Gebiet ist nicht mehr der friedliche Ort, der er einst war. Wenn nur diese Aufstände niemals stattgefunden hätten...", completion = "Meine milde Schildkrötensuppe wird Euch in einer kalten Nacht warm halten... falls es Euch überhaupt interessiert." }, enUS = { progress = "Any luck finding the ingredients?  I'll tell you, the alliance maggots are far too numerous in this area now... In my opinion, they have come far too close already...", completion = "My soothing turtle bisque will keep you warm on a cold night... if you care about that kind of thing." } })
apply(7383, { "classic", "forever" }, { deDE = { progress = "Die Druiden, unter Mitwirkung des Orakelbaums und des Erzdruiden, haben sich sorgsam um die Hege Teldrassils gekümmert. Wir haben jetzt zwar eine neue Heimat, doch unsere Unsterblichkeit haben wir noch nicht wiedererlangt.", completion = "In der Nähe des Orakelbaums... kann man fast spüren, wie die Weisheit Gestalt annimmt. Lasst mich mit der Geschichte fortfahren...\n\nTeldrassil wuchs und gedieh, und der Erzdruide wandte sich an die Großdrachen, um deren Segen zu erhalten, den sie in längst vergangenen Zeiten über Nordrassil verbreitet hatten. Nozdormu jedoch, der Lord der Zeit, weigerte sich, seinen Segen zu spenden und tadelte den Druiden wegen seiner Arroganz. Einig mit Nozdormu widersetzte sich auch Alexstrasza Staghelm und ohne ihren Segen entartete Teldrassil und wuchs auf unvorhersehbare Weise..." }, enUS = { progress = "Along with the druids, the Oracle Tree and the Arch Druid have been carefully monitoring the growth of Teldrassil. But though we have a new home, our immortal lives have not been restored.", completion = "To be in the presence of the Oracle Tree... it is almost to feel wisdom take form. Let me continue the telling...\n\nWith Teldrassil grown, the Arch Druid approached the dragons for their blessings, as the dragons had placed upon Nordrassil in ancient times. But Nozdormu, Lord of Time, refused to give his blessing, chiding the druid for his arrogance. In agreement with Nozdormu, Alexstrasza also refused Staghelm, and without her blessing, Teldrassil's growth has been flawed and unpredictable..." } })
apply(7486, { "classic", "forever" }, { deDE = { completion = "Hydraxis Stimme erklingt von der Wasseroberfläche aus...\n\n\"Wählt was am besten zu Euch passt, {name}. Möge es Euch vor den Feinden des Wasserlords schützen.\"" }, enUS = { completion = "Hydraxis' voice descends from the waters' surface...\n\n\"Choose that which best suits you, {name}.  May it protect you against the foes of the Waterlords.\"" } })
apply(7490, { "classic", "forever" }, { deDE = { progress = "<Thralls stoische Mine verschwindet für den Bruchteil einer Sekunde, als er den riesigen Kopf von Onyxia erblickt. Beinahe hätte er den mächtigen Doomhammer gezogen.>", completion = "Dies ist ein großartiger Sieg für die Horde, {name}. So viele male habt Ihr Euren Kriegshäuptling geehrt. Nun ist es an der Zeit, dass der Kriegshäuptling Euch seine Ehre erweist." }, enUS = { progress = "<Thrall's stoic demeanor changes for a split second when he sees the enormous head of Onyxia. The mighty Doomhammer was nearly unsheathed.>", completion = "This is a great victory for the Horde, {name}. So many times you have honored your Warchief. It is time for the Warchief to honor you." } })
apply(7491, { "classic", "forever" }, { deDE = { completion = "Wählt Eure Belohnung und lasst die Feierlichkeiten anlässlich Eures großen Sieges beginnen." }, enUS = { completion = "Choose your reward and let the celebration of your glorious victory begin." } })
apply(7495, { "classic", "forever" }, { deDE = { progress = "Bei Uthers Bart!", completion = "Für so viele Jahre habe ich unter ihrem Bann gestanden. Endlich wurde Gerechtigkeit geübt und die Ehre von Stormwind wieder hergestellt! Heute werden wir diesen glorreichen Sieg feiern!" }, enUS = { progress = "By Uther's beard!", completion = "For so many years I was held under her captivating gaze. Finally, to see justice meted and the honor of Stormwind restored! Today, we celebrate this glorious victory!" } })
apply(7496, { "classic", "forever" }, { deDE = { completion = "Nur wenige wurden bisher mit einer solchen Zeremonie geehrt, {name}. Bitte wählt Eure Belohnung aus, damit wir mit den Feierlichkeiten beginnen können." }, enUS = { completion = "Few are graced with such ceremony, {name}. Please, choose your reward so that we may begin the celebration." } })
apply(7498, { "classic", "forever" }, { deDE = { progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, {race}. Solltet Ihr noch weitere Folianten finden, zögert nicht sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu." }, enUS = { progress = "You have recovered a tome!", completion = "Excellent work, {race}. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes." } })
