apply(7504, { "classic", "forever" }, { deDE = { progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, {race}. Solltet Ihr noch weitere Folianten finden, zögert nicht sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu." }, enUS = { progress = "You have recovered a tome!", completion = "Excellent work, {race}. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes." } })
