apply(7506, { "classic", "forever" }, { deDE = { progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, {race}. Solltet Ihr noch weitere Folianten finden, zögert nicht sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu." }, enUS = { progress = "You have recovered a tome!", completion = "Excellent work, {race}. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes." } })
apply(7509, { "classic", "forever" }, { deDE = { progress = "Eines Tages wird vielleicht wieder jemand die Prismatische Klinge führen.", completion = "<Lydros murmelt etwas Unverständliches.>\n\nWie versprochen {class}, die Klinge von Quel'Serrar." }, enUS = { progress = "Perhaps one day, another will wield the prismatic blade.", completion = "<Lydros murmurs something unintelligible.>\n\nAs promised, {class}, the blade of Quel'Serrar." } })
apply(7581, { "classic", "forever" }, { deDE = { progress = "Allein das Blut der Wildhufsatyrn wird ausreichend sein.", completion = "Ah, welch' exzellente Ausbeute. Das Blut wird die magische Verteidigung der Verdammniswache  unterdrücken." }, enUS = { progress = "Only the blood of Wildspawn satyr will suffice.", completion = "Ah, a most excellent recovery. The blood will suppress the Doomguard's magical defenses." } })
apply(7582, { "classic", "forever" }, { deDE = { progress = "Die Dämonen von Hederine werden Euch ihre wertvollen Steine nicht kampflos überlassen, {name}.", completion = "Ich muss das Blut der Wildhufe lediglich mit diesen Kristallen vereinen, dann sollte das Gefängnis bereit sein." }, enUS = { progress = "The Hederine will not give up their precious gems without a fight, {name}.", completion = "I merely need to combine the blood of the Wildspawn with these crystals and the prison shall be ready for use." } })
apply(7601, { "classic", "forever" }, { deDE = { completion = "Junge, Junge, jetzt geht's los." }, enUS = { completion = "Oh boy, here we go again." } })
apply(7602, { "classic", "forever" }, { deDE = { progress = "Sagt es keinem, aber Niby ist bescheuert.", completion = "Gebt mir einen Moment, damit ich die drei Essenzen kombinieren und somit das Teufelsfeuer entfachen kann." }, enUS = { progress = "Don't tell anyone this but Niby is daft.", completion = "Give me a minute and I'll combine the essences into Fel fire." } })
apply(7603, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Euch verlaufen?", completion = "Geschäft ist Geschäft! Schnell, nehmt dies und schreibt dies nieder. Ich habe keine Zeit! Meine größte Beschwörung steht noch bevor!" }, enUS = { progress = "Did you get lost?", completion = "A deal is a deal! Quickly, take this and write this down. I don't have time! My greatest conjuration is upon us!" } })
apply(7622, { "classic", "forever" }, { deDE = { completion = "Eure Hartnäckigkeit und Euer Mut sind verblüffend, {class}. Ihr habt Euch das Recht den Splitter von Nordrassil tragen zu dürfen verdient. Es gilt nur noch eines zu tun: erlangt das Auge der Schatten wieder. Durchstreift die Welt danach." }, enUS = { completion = "Your tenacity and courage are astounding, {class}. You have earned the right to hold the Splinter of Nordrassil. Only one task remains: The Eye of Shadow must be recovered. Scour the world." } })
apply(7632, { "classic", "forever" }, { deDE = { progress = "<Vartrus stöhnt.>", completion = "Natürlich erkenne ich meine eigenen Blätter wieder. Schaut Euch das hier an! Es ist in perfektem Zustand.\n\nWie gut, dass Ihr es zurückgebracht habt, {class}.\n\nVielleicht könnt Ihr uns ja noch einen Dienst erweisen und wir Euch." }, enUS = { progress = "<Vartrus groans.>", completion = "Of course I recognize my own leaves. Look at that! It's in perfect condition.\n\nHow good of you to return it, {class}.\n\nPerhaps you could be of service to us and we to you." } })
apply(7634, { "classic", "forever" }, { deDE = { progress = "Abermals willkommen, junger {class}.", completion = "Mögen meine Blätter Eure Pfeile vor Schaden schützen. Mögen Eure Pfeile genau treffen. Mögen die Feinde unserer Welt niedergestreckt werden." }, enUS = { progress = "Welcome back, young {class}.", completion = "May my leaves provide your arrows protection from harm. May your arrows strike true. May the enemies of our world be smitten." } })
apply(7635, { "classic", "forever" }, { deDE = { progress = "Ich bin mir sicher, dass Euch das Auffinden und Töten eines schwarzen Drachens nicht leicht fallen wird, {name}. Verschwendet meine Zeit nicht mit nutzlosem Gerede.", completion = "Das war wohl ein ganz garstiger Drache. Die Sehne stinkt nach Bösen.\n\nGebt mir einen Moment Zeit, damit ich das Fleisch von dem Schmutz säubern  und die passenden Zauber anwenden kann." }, enUS = { progress = "I am certain that you will have little difficulty in finding and slaying a black dragon, {name}. Do not waste my time with idle chatter.", completion = "A most foul dragon this one was. The sinew reeks of evil.\n\nGive me a moment to cleanse the filth from this flesh and apply the proper enchantments." } })
apply(7636, { "classic", "forever" }, { deDE = { progress = "Lasst Euch nicht von ihren Verkleidungen täuschen!", completion = "Ihr habt uns einen großen Dienst erwiesen, {name}! Nehmt diesen Holzstab und kombiniert ihn mit der Bogensehen, zu deren Fertigung Stoma fähig ist. Zusammen ergibt sich daraus eine vorzügliche Waffe." }, enUS = { progress = "Do not be fooled by their disguises!", completion = "You have served us well, {name}! Take this stave and combine it with the bow string that Stoma is able to create. Together, they form a most formidable weapon." } })
apply(7649, { "classic", "forever" }, { deDE = { progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, mein Sohn.\n\n< Lydros reißt eine Seite aus dem Buch> \n\nIch bin sicher Ihr habt eine Verwendung für dieses Rezept." }, enUS = { progress = "You have recovered a tome!", completion = "Well done, my boy.\n\n<Lorekeeper Lydros tears out a page from the book.>\n\nI am sure you can make use of this recipe." } })
apply(7650, { "classic", "forever" }, { deDE = { progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, mein Sohn.\n\n< Lydros reißt eine Seite aus dem Buch> \n\nIch bin sicher Ihr habt eine Verwendung für dieses Rezept." }, enUS = { progress = "You have recovered a tome!", completion = "Well done, my boy.\n\n<Lorekeeper Lydros tears out a page from the book.>\n\nI am sure you can make use of this recipe." } })
apply(7651, { "classic", "forever" }, { deDE = { progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, mein Sohn.\n\n< Lydros reißt eine Seite aus dem Buch> \n\nIch bin sicher Ihr habt eine Verwendung für dieses Rezept." }, enUS = { progress = "You have recovered a tome!", completion = "Well done, my boy.\n\n<Lorekeeper Lydros tears out a page from the book.>\n\nI am sure you can make use of this recipe." } })
apply(7701, { "classic", "forever" }, { deDE = { progress = "Siieschte niichh dass isch beschäftischt bin?! Was *hicks* wollllt ihr denn *hicks*?", completion = "Isch hätt' nie gedacht, dasch ich diiieschem Ganoven nochmal in die Augen schauen würde!\n\nOhne den Rescht voo' ihm sieht er doch viiel bescha aus, findet Ihr nisch?\n\nHier's Eure Belohnung *hicks*, {race}." }, enUS = { progress = "Can't ya shee I'm bushy? What *hic* ish it ya be wantin? *hic*", completion = "I never thunk I'd be lookin' at thish ugly mug again!\n\nHe acshually looksh better without the resht o' him attached.\n\nHere's yer reward *hic*, {race}." } })
apply(7704, { "classic", "forever" }, { deDE = { description = "Ja, ja… wenn das nicht eine Überraschung ist. Das Zimmermädchen besaß ein riesiges verziertes Kissen und nun ist es Eures. Geht zu Evonice Sootsmoker, sie kann es nicht erwarten dieses Kissen zu bekommen und mit ihren fettigen Händen zu begrapschen. Bringt es ihr und schaut ob sie Euch dafür auch irgendwie für die Mühen entlohnt.", objectives = "Bringt das Kissen von Zimmermädchen Kissenquetscher zu Evonice Sootsmoker in der sengenden Schlucht." } })
apply(7721, { "classic", "forever" }, { deDE = { progress = "Ich könnte Euch zwar mit den technischen Details über den Nutzen der Elementarkerne langweilen, aber ich werde Euch lieber mit ein paar Münzen und anderen Belohnungen in Versuchung führen, damit ihr diese wichtige Aufgabe abschließt. So ist es die Wahrheit, seid Ihr wirklich fertig?", completion = "Hervorragend! Diese Kerne werden mich einige Zeit beschäftigen. Nicht zu vergessen, die Tatsache, dass es entlang der Küste nun weniger Elementare gibt, die uns Sorgen bereiten müssten. Möglicherweise muss ich mich jetzt nicht mehr in den Schlaf weinen, wenn ich daran denke, dass ich mein Lager ausgerechnet am schlimmsten Ort der Welt aufgeschlagen habe.\n\nVielen Dank {name}, für Eure Hilfe in dieser Angelegenheit. Es mag vielleicht meine Finanzen ein wenig überstrapazieren, aber ich denke ich möchte mein Wohlwollen Euch gegenüber in einer Weise ausdrücken, die Ihr versteht... ich hätte da einige Ausrüstung für Euch!" }, enUS = { progress = "While I could bore you with the technical details of the utility behind elemental cores, I will instead tempt you to completion of this important task by offering valuable coin and prizes for doing so.  Yon verily, are you finished?", completion = "Scrumdillyriffic!  These cores will keep me working for some time.  Add to that the benefit of there now being fewer elementals along the coast, and I might no longer cry myself to sleep at the prospect of having set up shop in perhaps the worst place imaginable!\n\nThank you, {name}, for your efforts on my behalf.  While it certainly straps me financially to do this, allow me to show you some gratitude you may understand and appreciate... loot!" } })
apply(7722, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Pläne gefunden?", completion = "Hoffentlich habt Ihr dem Kerl ordentlich in den Hintern getreten, {name}. Ragnaros weiß das er es verdient hat.\n\nAber jetzt zurück zum Geschäft." }, enUS = { progress = "Did you find the plans?", completion = "I hope you kicked his teeth in too, {name}. Ragnaros knows, he deserved it.\n\nNow we can get down to business." } })
apply(7723, { "classic", "forever" }, { deDE = { completion = "Ihr seid gar nicht mal so übel. Ich hab' Euch nen' kleines Geschenk besorgt." }, enUS = { completion = "Ye're a good lad, ye are. I got ye a lil' present fer yer troubles." } })
apply(7724, { "classic", "forever" }, { deDE = { completion = "<Hansel niest.>\n\nMist, ich glaub' ich krieg' eine Erkältung. Dieses verdammte kalte Klima hier." }, enUS = { completion = "<Hansel sneezes.>\n\nI think I'm gettin' a cold. Damn this frigid climate!" } })
apply(7726, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Elementarkerne bekommen, um die ich Euch gebeten habe?", completion = "Erstklassik, {name}, erstklassik! Diese Belohnung mag vielleicht nicht die wertvollste sein, die Ihr je erhalten habt. Stattdessen seid Euch sicher, dass meine Kameraden im Steamwheedle-Kartell von Euren Bemühungen erfahren werden!\n\nLasst es mich wissen, wenn Ihr mal wieder nach Arbeit sucht. Ich kann immer einige weitere Elementarkerne gebrauchen." }, enUS = { progress = "Have you managed to find the elemental cores I need?", completion = "Top notch, {name}, top notch!  While the coin I give you might not be the most you'll ever receive for such work, rest assured my comrades in the Steamwheedle Cartel will hear about your efforts!\n\nIf you are looking for anything else to do, then let me know.  I can always use more elemental cores and such." } })
apply(7728, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr wegen der Belohnung gekommen seid, müsst Ihr mir zuerst die gestohlenen Gegenstände übergeben.", completion = "Fantastische Arbeit! Und nun zu Euerer Belohnung." }, enUS = { progress = "If you're here for the reward, you're gonna have to give me the stolen goods.", completion = "Fantastic work! Now for your reward." } })
apply(7729, { "classic", "forever" }, { deDE = { progress = "Um sicher zu gehen, werden wir Euch mit und ohne Kleidung wiegen müssen.", completion = "15,9 Pfund! Das ist dann wohl ein neuer Rekord, für Blut und Gedärme je Kleidungsstück! Gratulation, {class}!" }, enUS = { progress = "We're gonna need to weigh you with and without clothes to be sure.", completion = "15.9 pounds! That may be a new record for blood and gut weight on apparel! Congratulations, {class}!" } })
apply(7730, { "classic", "forever" }, { deDE = { progress = "Was macht die Jagd, {name}? Seid Ihr hier, um von Eurem Erfolg zu berichten?", completion = "Gut gemacht, {class}. Obwohl man der hohen Ausbreitung der Zukk'ash mit nichts anderem als einer wahren Invasion entgegentreten kann, so habt Ihr uns doch etwas Zeit verschafft, um eine geeignete Strategie entwickeln zu können.\n\nIch werde dafür sorgen, dass man diese Knochenpanzer untersucht; wir müssen alles über sie herausfinden, bevor wir es mit dem zu tun bekommen, was sich unglücklicherweise als eine schwerliegendere Angelegenheit als angenommen entwickelt hat." }, enUS = { progress = "How goes the hunt, {name}?  Are you here to report your success?", completion = "Well done, {class}.  Though the extensiveness of the Zukk'ash presence will not be thwarted with anything less than a full-scale invasion, you have bought us some time so we can devise a proper strategy.\n\nI will be sure to have these carapaces analyzed; we'll need to learn everything about them before we deal with what has unfortunately turned into a much larger issue than we had anticipated." } })
apply(7731, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Zornstachel bereits bezwingen können?", completion = "Beeindruckend, {class}... sehr beeindruckend! Sollte Zornstachel wirklich eine ihrer stärksten Kreaturen sein, so werden sich die Untersuchungen der Bestie mit der Zeit als sehr wertvoll erweisen. Es liegt nun an mir sicher zu stellen, dass wir uns lange genug verteidigen, um davon profitieren zu können.\n\nBitte nehmt diese Prämie als Dankeszeichen des gesamten Camps an. Danke, {name}, gut gemacht." }, enUS = { progress = "Have you managed to bring down Stinglasher yet?", completion = "Impressive, {class}... most impressive!  If Stinglasher is indeed one of their strongest creatures, the study of the beast will prove to be quite valuable in time.  It's now my charge to make sure we defend ourselves long enough to take advantage of it.\n\nPlease accept this coin bounty as a token of the entire camp's thanks, {name}.  Well done." } })
apply(7732, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt... Ihr seht aus als wäret Ihr in wichtigen Angelegenheiten unterwegs. Kann ich Euch mit irgendetwas behilflich sein?", completion = "Ah, ich hatte es nicht anders erwartet. Diese Kreaturen, denen Ihr Euch gestellt habt... sind eine uralte Bedrohung, die die Horde weiterhin ignoriert. Es war weise von Hadoken, dass er dies - und Euch - zu mir bringen ließ.\n\nDie Zukk'ash sind nichts anderes als Kreaturen, die die Silithid genannt werden. Manch einer denkt, dass es sich dabei um unintelligente Unwesen handelt, aber lasst Euch versichern - sie sind eine weitaus schlimmere, ja sogar wesentlich schlimmere Bedrohung, als alles, was die Allianz aufbringen könnte.\n\nSolltet Ihr gewillt sein, könnte ich Eure Hilfe gebrauchen, um diese Bedrohung ans Licht zu bringen." }, enUS = { progress = "Greetings friend... you look as though you are on urgent business.  Is there something I can help you with?", completion = "Ah, I've been expecting this.  These creatures you faced... they are an ancient threat that the Horde continues to choose to ignore.  Hadoken was wise to bring this - and you - to me.\n\nThe Zukk'ash are nothing more than creatures called the silithid.  Some would think that they are a mindless nuisance, but let me assure you - they are a far, far worse threat than anything the Alliance could muster.\n\nIf you're willing and strong enough, I could use your aid in bringing this threat to light." } })
apply(7733, { "classic", "forever" }, { deDE = { progress = "Wenn diese Wutschrammyetibälge von eben so hoher Qualität sind wie ihre Gegenstücke der Wildschrammyetis, könnten sie gut und gerne so unverwüstlich wie Thorium sein!\n\nStellt Euch das einmal vor!", completion = "Exzellent, Exzellent! Ich denke diese Bälge werden Ihren Zweck hervorragend erfüllen - und mit der richtigen Behandlung werden sie noch um einiges widerstandsfähiger werden.\n\nDanke nochmal für Eure Hilfe, {name}. Hier, nehmt eine meiner neuesten Kreationen!" }, enUS = { progress = "If these Rage Scar yeti hides are anything like the quality displayed by their Feral Scar counterparts, they could very well be as resilient as thorium!\n\nImagine that!", completion = "Excellent, excellent!  These are going to work out incredibly well - I can already tell that they're going to be much harder when properly cured.\n\nThanks again for your help {name}.  Here - please take one of my latest creations." } })
apply(7734, { "classic", "forever" }, { deDE = { progress = "Wenn diese Wutschrammyetibälge von eben so hoher Qualität sind wie ihre Gegenstücke der Wildschrammyetis, könnten sie gut und gerne so unverwüstlich wie Thorium sein!\n\nStellt Euch das einmal vor!", completion = "Exzellent, Exzellent! Ich denke diese Bälge werden Ihren Zweck hervorragend erfüllen - und mit der richtigen Behandlung werden sie noch um einiges widerstandsfähiger werden.\n\nDanke nochmal für Eure Unterstützung, {name}. Hier, nehmt eine meiner neuesten Kreationen!" }, enUS = { progress = "If these Rage Scar yeti hides are anything like the quality displayed by their Feral Scar counterparts, they could very well be as resilient as thorium!\n\nImagine that!", completion = "Excellent, excellent!  These are going to work out incredibly well - I can already tell that they're going to be much harder when properly cured.\n\nThanks again for your aid, {name}.  Here - please take one of my latest creations." } })
apply(7735, { "classic", "forever" }, { deDE = { progress = "Was ist los, {name} - habt Ihr etwas Interessantes für mich?", completion = "Fantastisch! Es sieht so aus, als hättet Ihr die Mutter aller Yetibälge gefunden!\n\nIhr könnt Euch darauf verlassen, dass mir dieser Fund einiges Wert ist. Normalerweise zahle ich niemanden soviel für einen einzelnen Balg. Doch bin ich mir sicher, dass sich aus diesem hier etwas ganz Besonderes herstellen lässt. Danke {name}, das Ihr bei Eurem Fund an mich gedacht habt!" }, enUS = { progress = "What's this, {name} - you've got something special for me?", completion = "Incredible!  You may have found the granddaddy of all yeti hides with this!\n\nYou better believe I'll pay you for it.  I normally don't pay that much for a single hide, but I'm pretty sure I can make something special from it.  Thanks for thinking of me on this, {name}!" } })
apply(7738, { "classic", "forever" }, { deDE = { progress = "Was ist los, {name} - habt Ihr etwas Interessantes für mich?", completion = "Dieser Fund ist einfach unglaublich! Ich glaube dies hier ist der beste Balg den ich je gesehen habe!\n\nTatsächlich wäre hier eine großzügige Belohnung angebracht. Normalerweise zahle ich niemanden soviel für einen einzelnen Balg. Doch bin ich mir sicher, dass sich aus diesem hier etwas ganz Besonderes herstellen lässt. Danke {name}, das Ihr bei Eurem Fund an mich gedacht habt!" }, enUS = { progress = "What's this, {name} - you've got something special for me?", completion = "This is an incredible find!  I believe this is the finest yeti hide specimen I have ever seen!\n\nIndeed, this is certainly worthy of an appropriate bounty.  I normally don't pay that much for a single hide, but I'm confident I can make something special from it.  Thanks for thinking of me on this, {name}!" } })
apply(7761, { "classic", "forever" }, { deDE = { completion = "Ihr zuckt nicht einmal mit der Wimper, als Euch dass glühende Brandzeichen ins Fleisch gepresst wird. Unglaublich wie mutig Ihr seid!\n\nIhr seid nun mit dem Mal von Drakkisath gekennzeichnet. Viel Spass, beim Sturm auf die Burg!" }, enUS = { completion = "You don't even flinch as the smoldering brand is pressed into your flesh. You are so tough!\n\nYou now hold the Mark of Drakkisath. Have fun storming the castle." } })
apply(7783, { "classic", "forever" }, { deDE = { progress = "Ich wünschte, ich wäre mit Euch dort gewesen, {name}. Zu gerne hätte ich Nefarians Gesichtsausdruck gesehen, als er das Ende durch Eure Hand kommen sah.", completion = "Wieder einmal habt Ihr der Horde Ehre gebracht, {name}. Der Sohn von Deathwing ist tot." }, enUS = { progress = "I wish that I could have been there to see the look on the face of the beast as you struck the killing blow, {name}.", completion = "You have honored the Horde once more, {name}. The son of Deathwing lays dead. Surely, the evil one stirs." } })
apply(7785, { "classic", "forever" }, { deDE = { progress = "Werdet Ihr ihn aus seiner ewigen Gefangenschaft befreien?", completion = "Möget auf Euren Wegen von Schutz begleitet werden. Möge der Meister Eure Bemühungen segnen." }, enUS = { progress = "Will you release him from his eternal prison?", completion = "May you be protected in your crusade. May the Master bless your efforts." } })
apply(7786, { "classic", "forever" }, { deDE = { progress = "Zwingt die Welt in die Knie, wenn es sein muss!", completion = "Selbst in meinen Träumen wagte ich es nicht diesen Tag vorherzusehen.\n\nSehet, Sterblicher.\n\nSEHET DEN, DER ÄLTER ALS ALLES EXISTIERENDE IST!\n\nSEHET DEN, DER SICH TITANEN UND GÖTTERGLEICHEN STELLTE!\n\nERHEBT EUCH MEISTER! BEFREIT EUCH VON EUREN FESSELN!" }, enUS = { progress = "Bring the world to its knees if you must!", completion = "Even in dreams I did not dare foresee this day.\n\nBehold, mortal.\n\nBEHOLD HE WHO IS OLDER THAN EXISTENCE!\n\nBEHOLD HE WHO HAS FACED TITAN AND GOD ALIKE!\n\nRISE MY MASTER! BREAK FROM YOUR BONDS!" } })
apply(7787, { "classic", "forever" }, { deDE = { progress = "<Demitrian kauert in Eurer Gegenwart nieder.>", completion = "Ich flehe Euch an, verschont mich! Nehmt! Nehmt die Klinge! Lasst Demitrian sein erbärmliches Leben noch einmal neu angehen!" }, enUS = { progress = "<Demitrian cowers in your presence.>", completion = "Please, do not harm me! Take it! Take the blade! Leave Demitrian to reshape his pathetic life!" } })
apply(7815, { "classic", "forever" }, { deDE = { progress = "Na, und wie läufts mit der Jagd?", completion = "Mensch Alter! Ich kann dir nicht genug danken! Hoffentlich ist diese Angelrute hier gut genug als Belohnung." }, enUS = { progress = "How goes the hunt?", completion = "Oh, mon! I can't thank you enough! Hopefully this here fishing pole will be reward enough for the job." } })
apply(7816, { "classic", "forever" }, { deDE = { progress = "Haste ihn gefunden?", completion = "ALTER! Das ist fantastisch! Mit meinem besten Köder und ohne die Schnappkiefern da, kommen die Fische sicher in Scharen zurück." }, enUS = { progress = "Did you get it yet?", completion = "MON! This is fantastic! With my best lure and the snapjaw population down, the fish will pile up." } })
apply(7828, { "classic", "forever" }, { deDE = { completion = "Ah, gute Arbeit {race}. Die Revantusk danken Euch für Euren Beitrag." }, enUS = { completion = "A job well done, {race}. The Revantusk thank you for your contribution." } })
apply(7829, { "classic", "forever" }, { deDE = { completion = "Ihr habt Euch als ein wahrer Revantusk erwiesen, {name}. Gut gemacht." }, enUS = { completion = "You have proven a worthy ally to the Revantusk, {name}. Well done." } })
apply(7830, { "classic", "forever" }, { deDE = { progress = "Die Klingenschnabelhimmelsfürsten sind eine recht seltene Greifenspezies: Bekannt für Ihre enorme Fortpflanzungsfähigkeit und mörderische Nachkommen.", completion = "<Markhor untersucht den Federbusch.>\n\nIch frage mich, wieviele unserer Jäger dieses Biest erlegt hat, bevor ihm Gerechtigkeit wiederfuhr." }, enUS = { progress = "The Razorbeak Skylord is a much rarer breed of gryphon: One responsible for mating and creating murderous offspring.", completion = "<Markhor examines the plume.>\n\nI wonder how many of our hunters this beast devoured before you brought it to justice." } })
apply(7839, { "classic", "forever" }, { deDE = { progress = "Nehmt Euch vor den Trollen der Vilebranch dieser Gegend in Acht, {name}. Sie sind unbarmherziger, mörderischer Abschaum.", completion = "Mein Werkzeug! Ihr habt es gefunden! Was für ein glorreicher Tag! Ich danke Euch, {name}." }, enUS = { progress = "Watch out for the Vilebranch trolls of the region, {name}. They are ruthless, murderous filth.", completion = "My tools! You found them! Oh glorious day! Thank you, {name}." } })
apply(7840, { "classic", "forever" }, { deDE = { progress = "<Lard streicht sich über seinen riesigen Bauch.>\n\nLard so hungrig.", completion = "<Lard nimmt die riesige Fleischkeule von Euch und stopft sie sich in den Mund.>\n\nErste Sahne! Schön'n Dank.\n\nLard Euch machen tollen Picknickkorb für helfen Lard." }, enUS = { progress = "<Lard rubs his enormous belly.>\n\nLard so hungry.", completion = "<Lard takes the huge haunch of meat from you and stuffs it in his face.>\n\nDis hit da spot! Tanks little one.\n\nLard make you special picnic basket for help Lard." } })
apply(7841, { "classic", "forever" }, { deDE = { completion = "Sieht ganz so aus, als ob die Revantusk nun auch neue Verbündete haben, Mann. Ihr wart gründlich." }, enUS = { completion = "It be lookin' like the Revantusk are forgin' new alliances as well, mon! You done good." } })
apply(7842, { "classic", "forever" }, { deDE = { progress = "Die letzte Botschaft wird ihnen eine Heidenangst einjagen... oder sie verdammt wütend machen.", completion = "Oh Mann, das wird richtig gut werden. Nur noch ein Schritt und die Wildhammer werden sehen, dass sie es nicht mit den Trollen aufnehmen können!" }, enUS = { progress = "The last message gonna scare them off for sure. Either that or make them very, very angry.", completion = "Oh, mon, this gonna be good. One more step to go and Wildhammer see that they can't mess with troll!" } })
apply(7843, { "classic", "forever" }, { deDE = { progress = "Was wartet Ihr noch, Mann?", completion = "Ich wünschte, ich wär' dort gewesen, hätt' ihre Gesichter gesehen, Mann. Packen sie zusammen? Hau'n ab?\n\nKlasse Arbeit, {name}. Wirklich gut. Otho entlohnt Euch mit großem Mojo." }, enUS = { progress = "What's the hold up, mon?", completion = "I wish I coulda been there to see the look on their faces, mon. Are they packing up their bags? Leavin' town?\n\nYou done good, {name}. Real good. Otho reward you with the big mojo." } })
apply(7844, { "classic", "forever" }, { deDE = { completion = "Gut gemacht, {class}. Zul'jin selbst hätte es nicht besser machen können!" }, enUS = { completion = "Well done, {class}. Zul'jin himself could not have done a better job!" } })
apply(7845, { "classic", "forever" }, { deDE = { completion = "Ihr müsst schnell handeln, {name}. Eure Anwesenheit hat bestimmt schon die Wachen alarmiert." }, enUS = { completion = "You must act quickly, {name}. Surely the guards have been alerted to your presence." } })
apply(7846, { "classic", "forever" }, { deDE = { progress = "Ihr müsst Euch beeilen!", completion = "Endlich frei! Danke, {name}. In Revantusk wird man von Euren Taten erzählen!" }, enUS = { progress = "You must hurry!", completion = "Freedom at last! Thank you, {name}. Revantusk will know your deeds!" } })
apply(7847, { "classic", "forever" }, { deDE = { completion = "Ihr habt den Revantusk einen großen Dienst erwiesen, {name}! Wir schulden Euch sehr viel Dankbarkeit." }, enUS = { completion = "You have done the Revantusk a great service, {name}! We owe you a great debt of gratitude." } })
apply(7848, { "classic", "forever" }, { deDE = { progress = "Ihr müsst Eure Seele mit dem geschmolzenen Kern abstimmen, bevor Ihr Zugang erhaltet.", completion = "Ich bin jetzt in der Lage, Euch zum geschmolzenen Kern zu transportieren. Ihr braucht nur zu fragen." }, enUS = { progress = "You must attune your soul with the Molten Core before access is granted.", completion = "I am now able to transport you to the Molten Core. Ask and it shall be done." } })
